var DX_BODY = window.DX_BODY || {};

/* ==================== الغدد اللعابية والفم واللسان ==================== */

DX_BODY['sialolithiasis'] = {
  symptoms: {
    ar: 'العلامة المميّزة أنّ الألم مرتبط بالأكل ارتباطاً وثيقاً: ما إن ترى الطعام أو تضع أول لقمة في فمك حتى ينتفخ جانب واحد تحت الفكّ أو أمام الأذن انتفاخاً يُرى ويُلمس، ويشتدّ الشدّ فيه حتى يصير ألماً حادّاً، ثم يهدأ الورم تدريجياً خلال ساعة أو ساعتين بعد انتهاء الوجبة ليعود مع الوجبة التالية. والسبب أنّ الغدة تصنع اللعاب فلا يجد منفذاً فيحتقن خلف الحصاة. وقد يشعر المصاب بحبيبة صلبة تحت اللسان أو بطعم مالح مفاجئ حين تتحرّك الحصاة وينفجر اللعاب المحتقن. وإن دخلت عدوى على الانسداد تغيّر المشهد: احمرار وسخونة في الجلد فوق الغدة، وصديد يظهر عند فوّهة القناة داخل الفم، وحمّى وصعوبة في فتح الفم.',
    en: 'The distinguishing sign is that the pain is tightly bound to eating: the moment you see food or take the first bite, one side under the jaw or in front of the ear swells visibly and palpably, the tightness sharpens into a keen pain, then the swelling subsides over an hour or two after the meal ends only to return with the next one. The reason is that the gland keeps making saliva which finds no outlet and dams up behind the stone. The person may feel a hard grain under the tongue, or a sudden salty taste when the stone shifts and the trapped saliva bursts through. If infection is added the picture changes: redness and heat of the skin over the gland, pus appearing at the duct opening inside the mouth, fever and difficulty opening the mouth.'
  },
  cause: {
    ar: 'اللعاب سائل مشبع بالكالسيوم، وحين يركد أو يصير ثخيناً تترسّب أملاحه حول نواة صغيرة من خلايا أو مخاط فتكبر حبّة بحبّة حتى تصير حصاة تسدّ القناة. وأكثر ما تصاب الغدة تحت الفكّ لأنّ قناتها تصعد إلى أعلى ضدّ الجاذبية ولعابها أثخن وأغنى بالكالسيوم من غيرها. وأهمّ ما يهيّئ للحصاة قلّة شرب الماء والجفاف المزمن، والأدوية التي تجفّف الفم كأدوية الحساسية والضغط وبعض أدوية النفس، والتدخين، وأمراض تقلّل اللعاب مثل متلازمة شوغرن، والعلاج الإشعاعي على الرقبة، والنقرس. وتكثر عند الرجال في منتصف العمر، وقد تتكرّر في الغدة نفسها بعد إزالة أولى إن بقي السبب كما هو.',
    en: 'Saliva is a fluid saturated with calcium, and when it stagnates or thickens its salts settle around a small nucleus of cells or mucus and grow grain by grain into a stone that blocks the duct. The gland under the jaw is affected most, because its duct climbs upwards against gravity and its saliva is thicker and richer in calcium than the others. What most predisposes to a stone is drinking too little water and chronic dehydration, drugs that dry the mouth such as some allergy, blood-pressure and psychiatric medicines, smoking, diseases that reduce saliva such as Sjogren syndrome, radiotherapy to the neck, and gout. Stones are commoner in middle-aged men, and may recur in the same gland after a first removal if the cause remains unchanged.'
  },
  diagnosis: {
    ar: 'يبدأ الطبيب بجسّ أرضية الفم بإصبعين، واحدة داخل الفم وأخرى تحت الفكّ، فكثير من الحصوات يمكن تحسّسها بهذه الطريقة وحدها، ويفحص فوّهة القناة تحت اللسان ليرى هل يخرج منها لعاب صافٍ أم صديد أم لا شيء. ثم تُطلب الموجات فوق الصوتية على الغدة أوّلاً لأنّها متاحة وسريعة وبلا إشعاع وتُظهر الحصاة وحجم الغدة واحتقان القناة. وإن بقي الشكّ أو كانت الحصاة صغيرة أو عميقة يُلجأ إلى التصوير المقطعي بلا صبغة لأنّه أدقّ ما يكشف التكلّس ويحدّد موضعه بدقّة تكفي للتخطيط الجراحي. وقد يُستعان بمنظار القناة اللعابية الرفيع الذي يشخّص ويعالج في الجلسة نفسها. وتُؤخذ مسحة من الصديد إن وُجد لتحديد الجرثومة.',
    en: 'The doctor begins by feeling the floor of the mouth with two fingers, one inside the mouth and one under the jaw, since many stones can be felt by this alone, and inspects the duct opening under the tongue to see whether clear saliva, pus or nothing comes out. Ultrasound of the gland is then requested first because it is available, quick and free of radiation and shows the stone, the size of the gland and the swelling of the duct. If doubt remains or the stone is small or deep, a computed tomography scan without dye is used, being the most accurate way of showing calcification and locating it precisely enough to plan surgery. A fine salivary endoscope may also be used, diagnosing and treating in the same session. A swab of any pus is taken to identify the germ.'
  },
  treatment: {
    ar: 'أكثر الحصوات الصغيرة تخرج وحدها بتدبير بسيط يقوم عليه المريض نفسه: إكثار الماء، وتدليك الغدة من الخلف إلى الأمام باتجاه فتحة القناة، وكمّادات دافئة، ومصّ ما يحمض من الليمون لأنّه يحفّز اندفاع اللعاب فيدفع الحصاة أمامه. فإن ثبتت الحصاة فالخيارات متدرّجة: استخراجها من فوّهة القناة بشقّ صغير داخل الفم إن كانت قريبة، أو منظار القناة اللعابية الذي يدخل بأدوات دقيقة فيلتقطها أو يفتّتها، أو تفتيتها بالموجات الصادمة. وتُترك إزالة الغدة كلّها للحالات التي تكرّرت فيها النوبات وتلفت الغدة وصارت لا تفرز. وإن صاحبت الانسداد عدوى فيسبقها مضاد حيوي يختاره الطبيب، ثم يُعالج الانسداد بعد أن تهدأ. والوقاية بعدها شرب الماء وترك ما يجفّف الفم.',
    en: 'Most small stones come out on their own with simple measures the patient carries out himself: plenty of water, massaging the gland from behind forwards towards the duct opening, warm compresses, and sucking something sour such as lemon, which drives a rush of saliva that pushes the stone ahead of it. If the stone stays fixed the options are graded: removing it through the duct opening by a small cut inside the mouth if it is near, or salivary endoscopy which enters with fine instruments to grasp or fragment it, or breaking it with shock waves. Removing the whole gland is reserved for cases where attacks have recurred and the gland is damaged and no longer secretes. If infection accompanies the blockage, an antibiotic chosen by the doctor comes first and the blockage is dealt with once it settles. Prevention afterwards is water and avoiding what dries the mouth.'
  },
  seeDoctor: {
    ar: 'اذهب إلى الطوارئ في اليوم نفسه إن احمرّ الجلد فوق الغدة وسخن، أو ارتفعت حرارتك مع الورم، أو عجزت عن فتح فمك، أو انتشر الانتفاخ إلى أرضية الفم ورفع لسانك، أو ضاق نفسك أو صعب عليك البلع، فهذه علامات خرّاج قد ينزل إلى الرقبة وهو خطر. واحجز موعداً عادياً عند طبيب أنف وأذن وحنجرة إن تكرّر ورم الغدة مع الأكل أكثر من مرّة ولو زال بعدها، أو أحسست بحبيبة صلبة تحت لسانك، أو خرج صديد من فوّهة القناة. وانتبه إلى فارق مهمّ: الانتفاخ الذي يجيء ويروح مع الوجبات يوحي بحصاة، أمّا كتلة ثابتة لا تتغيّر مع الأكل ولا تختفي فليست حصاة وتحتاج فحصاً لسبب آخر ولا تُؤجَّل.',
    en: 'Go to the emergency department the same day if the skin over the gland turns red and hot, if fever accompanies the swelling, if you cannot open your mouth, if the swelling spreads into the floor of the mouth and lifts your tongue, or if your breathing tightens or swallowing becomes hard, since these signal an abscess that may track down the neck and is dangerous. Book an ordinary appointment with an ear, nose and throat doctor if the gland has swollen with eating more than once even though it settled afterwards, if you feel a hard grain under your tongue, or if pus comes from the duct opening. Note one important distinction: swelling that comes and goes with meals suggests a stone, whereas a fixed lump that neither changes with eating nor disappears is not a stone and needs assessment for another cause without delay.'
  },
  updated: '2026-09-08'
};

DX_BODY['salivary-gland-tumor'] = {
  symptoms: {
    ar: 'الشكوى الأولى غالباً كتلة اكتُشفت بالمصادفة أمام الأذن أو تحت شحمتها أو تحت الفكّ، لا تؤلم ولا تكبر بسرعة ولا تتغيّر مع الأكل، وقد يمرّ عليها شهور أو سنوات وصاحبها يظنّها شحماً. وهذا الهدوء نفسه لا يطمئن، لأنّ الحميد والخبيث يبدآن على الصورة ذاتها. وما يقلب الصورة علامات ثلاث: أن تصير الكتلة قاسية ملتصقة بما تحتها لا تتحرّك بين الأصابع، أو أن يظهر ألم فيها أو تنميل في الجلد فوقها، أو أن يضعف نصف الوجه فتتدلّى زاوية الفم ويصعب إغلاق العين على الجهة نفسها. وقد تظهر عقدة أخرى في الرقبة، أو ينمو الورم إلى داخل الفم فيدفع اللوزة والحنك للداخل، أو يضيق فتح الفم.',
    en: 'The first complaint is usually a lump found by chance in front of the ear, below its lobe, or under the jaw, which does not hurt, does not grow quickly and does not change with eating; months or years may pass while its owner takes it for fat. That very calm is no reassurance, because benign and malignant tumours begin looking exactly alike. Three signs turn the picture: the lump becoming hard and fixed to what lies beneath so it will not move between the fingers; pain in it or numbness of the skin over it; or weakness of half the face so the corner of the mouth droops and the eye on that side will not close. Another node may appear in the neck, or the tumour may grow inwards and push the tonsil and palate in, or narrow the opening of the mouth.'
  },
  cause: {
    ar: 'أورام الغدد اللعابية أنواع كثيرة تتراوح بين حميدة تماماً وخبيثة شرسة، وأكثرها موضعاً الغدة النكفية أمام الأذن، والقاعدة العملية أنّ كلّما صغرت الغدة زادت نسبة الخبث فيها: فأورام النكفية أكثرها حميد، وأورام الغدد اللعابية الصغيرة في الحنك واللسان أكثرها خبيث. وأشيع الحميد ورم يُسمّى الورم الغدّي متعدّد الأشكال، وهو بطيء لكنّه إن تُرك سنين طويلة قد يتحوّل. وعوامل الخطر المعروفة قليلة: سابقة إشعاع على الرأس والرقبة وهي أقواها، والتدخين يرتبط بنوع حميد بعينه، والتعرّض المهني لغبار الخشب والمعادن، وبعض الحالات العائلية. وأكثر الأورام تنشأ بلا سبب واضح يمكن تسميته للمريض.',
    en: 'Salivary gland tumours are many kinds, ranging from wholly benign to aggressively malignant, and the commonest site is the parotid gland in front of the ear. The practical rule is that the smaller the gland, the higher the proportion of malignancy: most parotid tumours are benign, while most tumours of the small salivary glands in the palate and tongue are malignant. The commonest benign one is called a pleomorphic adenoma, slow-growing but capable of transforming if left for many years. Known risk factors are few: previous radiation to the head and neck is the strongest, smoking is linked to one particular benign type, occupational exposure to wood and metal dust, and some familial conditions. Most tumours arise with no clear cause that can be named to the patient.'
  },
  diagnosis: {
    ar: 'يفحص الطبيب الكتلة بيديه ليعرف حجمها وقوامها وهل تتحرّك أم التصقت، ويختبر عصب الوجه بأن يطلب منك رفع الحاجبين وإغماض العينين بقوّة والابتسام وإظهار الأسنان، لأنّ ضعف العصب علامة خبث حتى يُثبت العكس. ثم الموجات فوق الصوتية أوّل صورة تُطلب لأنّها تفرّق الكتلة الصلبة من الكيسة ومن العقدة اللمفية. والخطوة الحاسمة أخذ خزعة بإبرة رفيعة تحت الموجات، فهي تعطي فكرة عن نوع الخلايا وتوجّه القرار الجراحي. ويُطلب الرنين المغناطيسي في الأورام العميقة لأنّه أدقّ ما يبيّن حدود الورم وعلاقته بعصب الوجه وامتداده إلى قاعدة الجمجمة. أمّا التشخيص النهائي القاطع فلا يُعرف غالباً إلا بعد فحص الورم كاملاً بعد استئصاله.',
    en: 'The doctor examines the lump by hand to learn its size and consistency and whether it moves or is fixed, and tests the facial nerve by asking you to raise your eyebrows, close the eyes tightly, smile and show the teeth, because weakness of that nerve is a sign of malignancy until proved otherwise. Ultrasound is the first image requested, since it separates a solid lump from a cyst and from a lymph node. The decisive step is a fine-needle biopsy under ultrasound, which gives an idea of the cell type and guides the surgical decision. Magnetic resonance imaging is requested for deep tumours, being the most accurate way of showing the tumour borders, its relation to the facial nerve and any extension to the skull base. The final, conclusive diagnosis, however, is usually known only after the whole tumour has been examined following its removal.'
  },
  treatment: {
    ar: 'الأساس جراحة يجريها جرّاح متمرّس في هذه المنطقة، لأنّ عصب الوجه يمرّ داخل الغدة النكفية نفسها فيلزم كشفه وتتبّع فروعه وحفظه أثناء رفع الورم، ولذلك تُستعمل مراقبة كهربائية للعصب أثناء العملية. ولا يُكتفى باستئصال الكتلة وحدها بل يُرفع معها هامش من الغدة السليمة لأنّ ترك محفظتها يجعل الورم يعود متعدّد البؤر ويصعب علاجه لاحقاً. فإن ثبت الخبث فقد يُضاف رفع عقد الرقبة، ثم علاج إشعاعي بعد الجراحة إن كان الورم عالي الدرجة أو بقيت حافّة ملوّثة أو غزا العصب. والمتابعة طويلة بالفحص والصور لأنّ بعض هذه الأورام يعود بعد سنين. وإن أُصيب عصب الوجه فهناك جراحات لإعادة تأهيله وحماية العين.',
    en: 'The mainstay is surgery by a surgeon experienced in this region, because the facial nerve runs inside the parotid gland itself, so it must be exposed, its branches traced and preserved while the tumour is lifted out, which is why electrical monitoring of the nerve is used during the operation. Removing the lump alone is not enough; a margin of healthy gland is taken with it, since leaving its capsule lets the tumour return in many spots and become hard to treat later. If malignancy is confirmed, neck node clearance may be added, then radiotherapy after surgery if the tumour is high grade, a margin was involved, or the nerve was invaded. Follow-up is long, with examination and imaging, because some of these tumours return after years. If the facial nerve is damaged there are operations to rehabilitate it and protect the eye.'
  },
  seeDoctor: {
    ar: 'احجز موعداً عند طبيب أنف وأذن وحنجرة خلال أسابيع قليلة لأيّ كتلة أمام الأذن أو تحت الفكّ بقيت أكثر من أسبوعين، حتى لو كانت بلا ألم ولم تكبر — فالألم ليس شرطاً وغيابه لا ينفي شيئاً. واطلب موعداً عاجلاً خلال أيام إن كبرت الكتلة بسرعة، أو صارت قاسية ثابتة لا تتحرّك تحت الجلد، أو ظهر تنميل في الجلد فوقها، أو ظهرت عقد أخرى في الرقبة، أو صعب فتح فمك. أمّا ضعف نصف الوجه أو تدلّي زاوية الفم أو عجزك عن إغلاق عين واحدة مع وجود كتلة في الغدة فحالة لا تُؤجَّل يوماً واحداً. ولا تقبل بأن يُقال لك إنّها مجرّد غدّة ملتهبة إن استمرّت شهراً بلا تغيّر — اطلب صورة موجات صوتية على الأقلّ.',
    en: 'Book an appointment with an ear, nose and throat doctor within a few weeks for any lump in front of the ear or under the jaw that has lasted more than two weeks, even if painless and not growing, since pain is not required and its absence rules nothing out. Ask for an urgent appointment within days if the lump grows quickly, becomes hard and fixed under the skin, if numbness appears in the skin over it, if other nodes appear in the neck, or if opening your mouth becomes difficult. Weakness of half the face, drooping of the corner of the mouth, or inability to close one eye alongside a gland lump is a situation that must not be put off for a single day. Do not accept being told it is merely an inflamed gland if it has lasted a month unchanged; ask at least for an ultrasound.'
  },
  updated: '2026-09-08'
};

DX_BODY['oral-leukoplakia'] = {
  symptoms: {
    ar: 'الغالب أنّ الشخص لا يشكو شيئاً إطلاقاً، وإنّما يلمح في المرآة أو يكتشف طبيب الأسنان بقعة بيضاء أو رمادية على باطن الخدّ أو على اللسان من جانبه أو تحته أو على اللثة أو أرضية الفم. البقعة لا تؤلم ولا تحكّ، وأهمّ صفة فيها أنّها لا تُمسح: إن حككتها بشاش أو بفرشاة لم تزل ولم ينكشف تحتها احمرار، وهذا ما يفرّقها عن فطريات الفم. وقد يكون سطحها أملس رقيقاً أو خشناً متجعّداً كقشرة، وقد تكون بقعة واحدة أو عدّة بقع. والصورة التي تستدعي انتباهاً أكبر أن تختلط بها مناطق حمراء مخملية، أو تصير غير متجانسة السطح، أو تتقرّح، أو يبدأ صاحبها يشعر فيها بحرقة أو خشونة أو ألم عند الحوامض.',
    en: 'Most often the person complains of nothing at all, and instead glimpses in the mirror, or the dentist discovers, a white or grey patch on the inner cheek, on the side or under-surface of the tongue, on the gum or on the floor of the mouth. The patch neither hurts nor itches, and its most important feature is that it cannot be wiped off: rubbing it with gauze or a brush neither removes it nor reveals redness beneath, which is what separates it from oral thrush. Its surface may be smooth and thin or rough and wrinkled like a crust, and it may be a single patch or several. The picture that demands greater attention is one mixed with velvety red areas, an uneven surface, ulceration, or the onset of burning, roughness or pain with sour foods.'
  },
  cause: {
    ar: 'البقعة تنشأ حين يردّ غشاء الفم على تهيّج مزمن بأن يزيد سماكة طبقته القرنية فتبدو بيضاء. وأقوى المسبّبات التبغ بكلّ صوره: السجائر والمعسل والغليون، وأشدّها التبغ الذي يوضع في الفم كالشمّة والسواك المخلوط بالتبغ ومضغ التنبول والقات في بعض البلدان، لأنّه يلامس النسيج ساعات كلّ يوم. ويضاعف الكحول أثر التبغ حين يجتمعان. وهناك تهيّج ميكانيكي: حافّة سنّ مكسور أو طقم غير محكم يحكّ الخدّ في الموضع نفسه سنين. وتزيد الخطورة مع فيروس الورم الحليمي في بعض المواضع، ومع ضعف المناعة. والمهمّ في الفهم أنّ الطلاوة ليست سرطاناً، لكنّها آفة سابقة له: نسبة منها تتحوّل مع الوقت، وأخطرها ما كان على اللسان من أسفل أو على أرضية الفم أو خالطه احمرار.',
    en: 'The patch arises when the lining of the mouth answers chronic irritation by thickening its horny layer, which then looks white. The strongest cause is tobacco in all its forms: cigarettes, waterpipe and pipe, and worst of all tobacco placed in the mouth, such as snuff, tobacco-mixed chewing sticks, betel and khat in some countries, because it touches the tissue for hours every day. Alcohol multiplies the effect of tobacco when the two combine. There is also mechanical irritation: the edge of a broken tooth or an ill-fitting denture rubbing the same spot for years. Risk rises with human papillomavirus at some sites and with weakened immunity. What matters in understanding it is that leukoplakia is not cancer but a lesion that precedes it: a proportion transforms with time, and the most dangerous are those under the tongue, on the floor of the mouth, or mixed with redness.'
  },
  diagnosis: {
    ar: 'الخطوة الأولى فحص الفم كلّه بضوء جيّد ومرآة، مع قلب الشفتين ورفع اللسان لرؤية سطحه السفلي وأرضية الفم لأنّها أخطر المواضع وأكثرها إفلاتاً من النظر، ويُجسّ ما تحت البقعة بالإصبع لمعرفة هل صار النسيج تحتها قاسياً. ثم تُجرّب إزالة السبب الظاهر ويُعاد الفحص بعد أسبوعين: فإن زالت البقعة فقد كانت تهيّجاً أو فطراً لا طلاوة. أمّا إن بقيت بعد أسبوعين من رفع السبب فالخزعة هي الفيصل، وتؤخذ من أشدّ مكان في البقعة سماكةً أو احمراراً أو تقرّحاً لا من طرفها، لأنّ الفحص المجهري وحده يقول أفيها تبدّل في الخلايا أم لا ودرجته. ويُجسّ عنق المريض بحثاً عن عقد، ويُوثَّق مكان البقعة وقياسها بالصورة للمقارنة في المتابعة.',
    en: 'The first step is examining the whole mouth with good light and a mirror, turning the lips out and lifting the tongue to see its under-surface and the floor of the mouth, since these are the most dangerous sites and the easiest to miss, and feeling beneath the patch with a finger to learn whether the tissue under it has hardened. The obvious cause is then removed and the examination repeated after two weeks: if the patch clears it was irritation or fungus, not leukoplakia. If it persists two weeks after the cause is removed, biopsy is decisive, taken from the thickest, reddest or most ulcerated part of the patch rather than its edge, because microscopy alone tells whether the cells have changed and to what degree. The neck is felt for nodes, and the site and measurements of the patch are recorded photographically for comparison at follow-up.'
  },
  treatment: {
    ar: 'العلاج الأول والأهمّ ليس دواءً بل إزالة السبب: ترك التبغ بكلّ أشكاله والامتناع عن الكحول، وإصلاح السنّ المكسور أو الطقم الذي يحكّ. وكثير من البقع يتراجع أو يختفي بهذا وحده خلال أشهر، وهذا ما يجعل الإقلاع جزءاً من العلاج لا نصيحة عابرة. فإن أظهرت الخزعة تبدّلاً في الخلايا، أو كانت البقعة في موضع خطر كأرضية الفم أو أسفل اللسان، أو خالطها احمرار، أو كانت واسعة، فالاتجاه إزالتها كاملة إمّا بالجراحة أو بالليزر أو بالتجميد، مع فحص ما أُزيل مجهرياً. ومهما كان القرار تبقى المتابعة الدورية ركناً لا يُترك، بفحص الفم كلّ بضعة أشهر وتصويره، لأنّ البقعة قد تعود في مكانها أو تظهر بقعة جديدة في موضع آخر، ولأنّ التحوّل يقع بلا أعراض.',
    en: 'The first and most important treatment is not a medicine but removal of the cause: giving up tobacco in every form, avoiding alcohol, and repairing the broken tooth or rubbing denture. Many patches shrink or vanish with this alone over months, which makes quitting part of the treatment rather than a passing piece of advice. If the biopsy shows cell change, or the patch sits in a dangerous site such as the floor of the mouth or under the tongue, or is mixed with redness, or is wide, the tendency is to remove it completely by surgery, laser or freezing, with microscopic examination of what was taken. Whatever the decision, regular follow-up remains a pillar that is never dropped, with examination of the mouth every few months and photographs, because the patch may return in place or a new one appear elsewhere, and because transformation happens without symptoms.'
  },
  seeDoctor: {
    ar: 'اعرض فمك على طبيب أسنان أو طبيب أنف وأذن وحنجرة خلال أيام إن رأيت بقعة بيضاء أو قرحة أو تورّماً في فمك بقي أكثر من أسبوعين بلا شفاء، وهذه هي القاعدة الذهبية: أسبوعان. واطلب موعداً عاجلاً لا يُؤجَّل إن كانت البقعة مخلوطة بأحمر مخملي، أو تقرّحت ونزفت من أقلّ لمسة، أو قسا ما تحتها، أو صارت مؤلمة، أو ظهرت على أرضية الفم أو تحت اللسان، أو صحبها خدر في الشفة أو اللسان، أو ظهرت عقدة في رقبتك، أو رخّ سنّ بلا سبب، أو صعب عليك البلع أو فتح الفم. وإن كنت مدخّناً أو تستعمل الشمّة والسواك المخلوط بالتبغ فاجعل فحص فمك عند طبيب الأسنان عادةً سنويّة ولو لم تشكُ شيئاً.',
    en: 'Show your mouth to a dentist or an ear, nose and throat doctor within days if you see a white patch, ulcer or swelling that has lasted more than two weeks without healing; two weeks is the golden rule. Ask for an urgent, unpostponed appointment if the patch is mixed with velvety red, if it has ulcerated and bleeds at the lightest touch, if the tissue under it has hardened, if it has become painful, if it lies on the floor of the mouth or under the tongue, if numbness of the lip or tongue accompanies it, if a node has appeared in your neck, if a tooth has loosened for no reason, or if swallowing or opening the mouth has become hard. If you smoke or use snuff or tobacco-mixed chewing sticks, make a dental examination of your mouth a yearly habit even with no complaint at all.'
  },
  updated: '2026-09-08'
};

DX_BODY['geographic-tongue'] = {
  symptoms: {
    ar: 'يلمح الشخص في المرآة بقعاً حمراء ملساء على ظهر اللسان أو جانبيه، فقدت الحليمات الصغيرة التي تكسو سطح اللسان فبدت كأنّها مناطق عارية، ويحيط بكلّ بقعة إطار أبيض أو مصفرّ مرتفع قليلاً، فيصير المنظر كخريطة قارّات وبحار. وأغرب ما فيها أنّها ترتحل: بقعة تشفى في موضع وتظهر أخرى في موضع مجاور خلال أيام أو أسابيع، فيتغيّر شكل الخريطة كلّما نظرت. وأكثر المصابين لا يشعرون بشيء ولا يكتشفونها إلا مصادفةً أو من طبيب الأسنان. وقد يشكو بعضهم حسّاسية أو لسعاً خفيفاً عند الحوامض والطعام الحارّ والمالح والجبن والنعناع. وقد تصاحبها شقوق عميقة في سطح اللسان تسمّى اللسان المشقّق وهي أيضاً حميدة.',
    en: 'The person glimpses in the mirror smooth red patches on the top or sides of the tongue that have lost the small papillae covering its surface, so they look like bare areas, each ringed by a slightly raised white or yellowish border, making the picture resemble a map of continents and seas. The strangest thing about them is that they travel: a patch heals in one place while another appears next to it within days or weeks, so the shape of the map changes each time you look. Most affected people feel nothing and discover it only by chance or from a dentist. Some complain of sensitivity or a mild sting with sour, spicy or salty foods, cheese and mint. It may be accompanied by deep grooves on the tongue surface, called fissured tongue, which is also harmless.'
  },
  cause: {
    ar: 'السبب الدقيق غير معروف، والمفهوم أنّ الأمر التهاب سطحي حميد يتنقّل في الغشاء المخاطي للسان، تتساقط فيه الحليمات في منطقة ثم تنمو من جديد بينما تسقط في منطقة أخرى. وهي حالة شائعة تصيب نسبة معتبرة من الناس في كلّ الأعمار، وتكثر في العائلة الواحدة ممّا يرجّح استعداداً وراثياً. وترتبط ارتباطاً معروفاً باللسان المشقّق وبالصدفية، حتى إنّ بعض الباحثين يعدّها صورة من الصدفية في الفم، كما ترتبط بالحساسية والربو والإكزيما. ويلاحظ كثير من المصابين أنّها تشتدّ في أوقات التوتّر ونقص النوم، وعند النساء مع تغيّرات الدورة أو الحمل أو حبوب منع الحمل. وليست معدية إطلاقاً، ولا علاقة لها بالنظافة ولا بنوع الطعام، ولا تتحوّل إلى ورم أبداً.',
    en: 'The exact cause is unknown; it is understood as a harmless surface inflammation that migrates through the lining of the tongue, in which the papillae shed in one area and regrow while shedding elsewhere. It is common, affecting a considerable proportion of people at all ages, and clusters in families, which suggests an inherited tendency. It has a known association with fissured tongue and with psoriasis, so much so that some researchers count it a form of psoriasis in the mouth, and it is also linked to allergy, asthma and eczema. Many sufferers notice it flares at times of stress and poor sleep, and in women with cycle changes, pregnancy or contraceptive pills. It is not contagious at all, has nothing to do with hygiene or with any particular food, and never turns into a tumour.'
  },
  diagnosis: {
    ar: 'التشخيص بالنظر وحده في الأغلب: شكل البقع الحمراء الملساء بحافّة بيضاء متعرّجة، وتنقّلها من موضع إلى آخر بين زيارة وأخرى، صورة مميّزة لا تحتاج تحليلاً ولا خزعة. ويسأل الطبيب عن مدّة الحالة وهل تتغيّر أماكن البقع، لأنّ الترحال نفسه هو الدليل. وأهمّ ما يُبذل فيه الجهد هو استبعاد ما يشبهها: فطريات الفم التي تُكشط فتنزف قليلاً وتستجيب لمضادّ الفطر، والطلاوة وهي بقعة بيضاء ثابتة لا تتنقّل ولا بدّ من خزعتها، والحزاز المسطّح بخطوطه الشبكية البيضاء، ونقص الحديد أو فيتامين ب اثني عشر الذي يجعل اللسان أملس محرقاً كلّه لا بقعاً. ولذلك قد يُطلب تحليل دم بسيط إن كانت الحرقة شديدة أو اللسان أحمر كلّه.',
    en: 'The diagnosis is usually made by looking alone: the shape of smooth red patches with a wavy white border, and their movement from place to place between one visit and the next, is a distinctive picture needing no test and no biopsy. The doctor asks how long it has lasted and whether the patches change position, because the travelling itself is the proof. The greatest effort goes into excluding what resembles it: oral thrush, which scrapes off with slight bleeding and responds to antifungal treatment; leukoplakia, a fixed white patch that does not travel and must be biopsied; lichen planus with its white lacy lines; and deficiency of iron or vitamin B twelve, which makes the whole tongue smooth and burning rather than patchy. A simple blood test may therefore be requested if the burning is severe or the whole tongue is red.'
  },
  treatment: {
    ar: 'لا تحتاج هذه الحالة علاجاً في الأصل لأنّها حميدة ولا تؤذي ولا تتطوّر، وأهمّ ما يُقدَّم للمريض هو الطمأنينة نفسها بعد أن يُشرح له أنّ ما يراه ليس عدوى ولا آفة خطيرة. وحين تسبّب حرقة أو لسعاً فالتدبير يقوم على تجنّب ما يهيّج: الحوامض كالليمون والطماطم والأناناس، والحارّ الشديد، والمالح، والمشروبات الغازية، ومعاجين الأسنان القوية النكهة بالنعناع والقرفة أو الحاوية على رغويات مهيّجة. وقد ينفع تبريد الفم بشيء بارد أو مصّ قطعة ثلج أثناء النوبة. وإن كان الانزعاج شديداً ومستمرّاً فقد يصف الطبيب موضعياً ما يهدّئ الالتهاب لفترة قصيرة. وتُنصح متابعة الحالة إن ثبتت بقعة واحدة في مكانها ولم ترتحل، لأنّها حينئذ ليست هذا التشخيص.',
    en: 'This condition needs no treatment in principle, being harmless, non-damaging and non-progressive, and the most important thing offered to the patient is reassurance itself, once it is explained that what he sees is neither an infection nor a serious lesion. When it causes burning or stinging, management rests on avoiding irritants: sour foods such as lemon, tomato and pineapple, very spicy and salty food, fizzy drinks, and strongly flavoured toothpastes with mint or cinnamon or containing irritant foaming agents. Cooling the mouth with something cold or sucking a piece of ice during a flare may help. If the discomfort is severe and persistent the doctor may prescribe something topical to calm the inflammation for a short period. Follow-up is advised if a single patch stays fixed in place and does not travel, because it is then not this diagnosis.'
  },
  seeDoctor: {
    ar: 'لا حاجة إلى الطوارئ في هذه الحالة إطلاقاً. لكن احجز موعداً عادياً عند طبيب الأسنان أو الأنف والأذن والحنجرة إن ثبتت بقعة واحدة في موضعها أكثر من أسبوعين ولم ترتحل ولم تشفَ، لأنّ الثبات ينقض هذا التشخيص ويستدعي فحصاً آخر. واطلب الموعد كذلك إن تقرّحت البقعة أو نزفت، أو قسا ما تحتها، أو صار اللسان كلّه أملس أحمر لامعاً، أو صحبتها شحوب وتعب وتساقط شعر فقد يكون وراءها نقص حديد أو فيتامين، أو صار الألم يمنعك من الأكل والشرب، أو ظهرت بقع بيضاء تُكشط في فمك أو في حلقك. وإن كنت مدخّناً وظهرت في لسانك بقعة بيضاء ثابتة لا تتنقّل فلا تنسبها إلى اللسان الجغرافي واعرضها فوراً.',
    en: 'There is no call for the emergency department in this condition at all. But book an ordinary appointment with a dentist or an ear, nose and throat doctor if a single patch stays fixed in place for more than two weeks without travelling and without healing, because that fixity contradicts the diagnosis and calls for another assessment. Ask for an appointment too if the patch ulcerates or bleeds, if the tissue under it hardens, if the whole tongue turns smooth, red and glossy, if it comes with pallor, fatigue and hair loss since iron or vitamin deficiency may lie behind it, if pain begins to stop you eating and drinking, or if white patches that scrape off appear in your mouth or throat. And if you smoke and a fixed, non-travelling white patch appears on your tongue, do not put it down to geographic tongue; have it seen at once.'
  },
  updated: '2026-09-08'
};

DX_BODY['burning-mouth'] = {
  symptoms: {
    ar: 'الشكوى إحساس بالحرق أو اللسع أو الخدر في طرف اللسان وسطحه، وقد يمتدّ إلى الشفتين وسقف الفم وداخل الخدّين، يشبّهه المصاب بمن شرب شاياً مغلياً فكوى فمه. ولهذا الألم إيقاع يوميّ مميّز: يستيقظ الشخص صباحاً وفمه مرتاح أو شبه مرتاح، ثم يبدأ الحرق ويتصاعد ساعةً بعد ساعة حتى يبلغ أشدّه في المساء، ويهدأ أثناء الأكل والشرب بخلاف كلّ الآلام الفموية الأخرى. ويصاحبه غالباً جفاف في الفم يشعر به المريض ولو كان اللعاب كافياً بالقياس، وطعم معدني أو مرّ ثابت، وتبدّل في تذوّق الأطعمة. والمحيّر أنّ الفم عند الفحص يبدو سليماً تماماً: لا احمرار ولا قرحة ولا بقعة تفسّر هذا كلّه، فيُتّهم المريض بالمبالغة وهو صادق في ألمه.',
    en: 'The complaint is a burning, stinging or numb sensation at the tip and surface of the tongue, which may spread to the lips, the roof of the mouth and the inside of the cheeks, likened by sufferers to having drunk boiling tea and scalded the mouth. This pain has a distinctive daily rhythm: the person wakes with a comfortable or nearly comfortable mouth, then the burning begins and climbs hour by hour to its peak in the evening, and it eases during eating and drinking, unlike every other oral pain. It is usually accompanied by a felt dryness of the mouth even when saliva measures adequate, a persistent metallic or bitter taste, and altered taste of foods. What baffles is that the mouth on examination looks entirely normal: no redness, ulcer or patch to explain any of it, so the patient is accused of exaggerating while being truthful about the pain.'
  },
  cause: {
    ar: 'حين لا يُوجد سبب ظاهر تُعدّ الحالة اضطراباً في الأعصاب الدقيقة التي تنقل الإحساس والتذوّق في الفم: إشارات ألم تنطلق من غير مثير، تشبه ما يحدث في الآلام العصبية في مواضع أخرى من الجسم. وتصيب النساء أكثر من الرجال، وتكثر بعد سنّ اليأس، ويظهر أنّ للتغيّرات الهرمونية دوراً. ويضاعفها القلق والاكتئاب واضطراب النوم، ليس لأنّها نفسية المنشأ بل لأنّ الجهاز العصبي يضخّم الألم تحت الضغط. ولا بدّ قبل قبول هذا التفسير من استبعاد أسباب حقيقية تعطي الشكوى نفسها: جفاف اللعاب، وفطريات الفم الخفيّة، ونقص الحديد أو حمض الفوليك أو فيتامين ب اثني عشر أو الزنك، والسكّري، وقصور الدرقية، والارتجاع الحمضي، وحساسية من مواد الطقم أو الحشوات، وصرير الأسنان ودفع اللسان على الأسنان، وبعض أدوية الضغط.',
    en: 'When no visible cause is found, the condition is regarded as a disorder of the fine nerves that carry sensation and taste in the mouth: pain signals firing without a trigger, resembling nerve pain elsewhere in the body. It affects women more than men, is commonest after the menopause, and hormonal change appears to play a part. Anxiety, depression and disturbed sleep magnify it, not because its origin is psychological but because the nervous system amplifies pain under strain. Before accepting this explanation, real causes giving the same complaint must be excluded: dry saliva, hidden oral thrush, deficiency of iron, folate, vitamin B twelve or zinc, diabetes, an underactive thyroid, acid reflux, allergy to denture or filling materials, tooth grinding and pressing the tongue against the teeth, and some blood-pressure medicines.'
  },
  diagnosis: {
    ar: 'لا يوجد تحليل واحد يثبت هذه الحالة، وإنّما تُشخَّص بالاستبعاد بعد بحث منظّم. يبدأ الطبيب بفحص الفم كلّه بحثاً عن أيّ آفة تفسّر الحرقة: بقعة بيضاء أو حمراء، فطريات، حزاز مسطّح، تشقّق زوايا الفم، طقم يحكّ، حافّة سنّ حادّة، وعلامات صرير أو دفع اللسان على الأسنان. ثم تُطلب تحاليل دم تشمل صورة الدم والحديد والفيريتين وفيتامين ب اثني عشر وحمض الفوليك والزنك وسكّر الدم التراكمي ووظائف الدرقية، لأنّ نقص أيّ منها يعطي حرقة اللسان نفسها وهو قابل للعلاج. وقد تؤخذ مسحة للفطريات لأنّ الفطر قد لا يُرى بالعين. ويُقاس تدفّق اللعاب إن كان الجفاف بارزاً، ويُسأل عن الأدوية كلّها لأنّ بعضها متّهم معروف.',
    en: 'No single test proves this condition; it is diagnosed by exclusion after an organised search. The doctor begins by examining the whole mouth for any lesion that would explain the burning: a white or red patch, thrush, lichen planus, cracked corners of the mouth, a rubbing denture, a sharp tooth edge, and signs of grinding or of pressing the tongue against the teeth. Blood tests are then requested, including a blood count, iron and ferritin, vitamin B twelve, folate, zinc, long-term blood sugar and thyroid function, since a lack of any of these gives the same burning tongue and is treatable. A swab for fungus may be taken, because it may not be visible to the eye. Saliva flow is measured if dryness is prominent, and all medicines are reviewed, since some are known suspects.'
  },
  treatment: {
    ar: 'إن وُجد سبب قابل للتصحيح فعلاجه يزيل الشكوى غالباً: تعويض النقص الغذائي، وعلاج الفطريات، وضبط السكّر أو الدرقية، وتعديل الطقم أو الحشوة المسبّبة، وضبط الارتجاع، ومراجعة الأدوية مع الطبيب الذي وصفها. أمّا حين لا يُوجد سبب فالتدبير يشبه تدبير أيّ ألم عصبي مزمن: أدوية تهدّئ الأعصاب المفرطة الاستثارة يختارها الطبيب ويبدأها بمقدار قليل ثم يرفعه ببطء، وقد تُستعمل موضعياً في الفم قبل اللجوء إلى الأقراص. ويُنصح بترك ما يهيّج: معاجين الأسنان بالنعناع القوي والقرفة والرغويات، والغسولات الكحولية، والحوامض، والحارّ، والتبغ. وترطيب الفم بالماء ومصّ الثلج يخفّف. والعلاج النفسي السلوكي وضبط النوم والقلق يقلّلان شدّة الألم فعلياً. والصبر ركن: التحسّن تدريجيّ لا فوريّ.',
    en: 'If a correctable cause is found, treating it usually removes the complaint: replacing a nutritional deficiency, treating thrush, controlling diabetes or the thyroid, adjusting the offending denture or filling, controlling reflux, and reviewing medicines with the doctor who prescribed them. When no cause is found, management resembles that of any chronic nerve pain: medicines that calm over-excitable nerves, chosen by the doctor and begun at a small amount then raised slowly, sometimes used topically in the mouth before resorting to tablets. Avoiding irritants is advised: toothpastes with strong mint, cinnamon or foaming agents, alcohol-based mouthwashes, sour and spicy food, and tobacco. Moistening the mouth with water and sucking ice eases it. Cognitive behavioural therapy and control of sleep and anxiety genuinely reduce the pain. Patience is a pillar: improvement is gradual, not immediate.'
  },
  seeDoctor: {
    ar: 'ليست حالة طوارئ، لكن احجز موعداً عند طبيب الأسنان أو الأنف والأذن والحنجرة إن استمرّت الحرقة أكثر من أسبوعين، ولا تكتفِ بتغيير معجون الأسنان وانتظار الفرج، لأنّ أسباباً قابلة للعلاج تماماً مثل نقص الحديد أو فيتامين ب اثني عشر أو فطريات خفيّة تعطي هذه الشكوى بالضبط ولن تُكشف إلا بالفحص والتحليل. واطلب موعداً عاجلاً خلال أيام إن ظهرت في فمك قرحة أو بقعة بيضاء أو حمراء ثابتة، أو خدر حقيقي في الشفة أو اللسان لا مجرّد حرقة، أو تورّم، أو صعوبة في البلع أو الكلام، أو نقص وزن، أو كتلة في الرقبة، فهذه ليست من هذه المتلازمة. واذكر لطبيبك كلّ دواء تتناوله بلا استثناء، وإن رافق الألم يأس أو أفكار مؤذية فاطلب المساعدة النفسية فوراً.',
    en: 'This is not an emergency, but book an appointment with a dentist or an ear, nose and throat doctor if the burning lasts more than two weeks, and do not settle for changing toothpaste and waiting for relief, because entirely treatable causes such as iron or vitamin B twelve deficiency or hidden thrush give exactly this complaint and will be found only by examination and testing. Ask for an urgent appointment within days if an ulcer or a fixed white or red patch appears in your mouth, if there is true numbness of the lip or tongue rather than mere burning, if there is swelling, difficulty swallowing or speaking, weight loss, or a lump in the neck, since none of these belong to this syndrome. Tell your doctor about every medicine you take without exception, and if despair or thoughts of harm accompany the pain, seek psychological help at once.'
  },
  updated: '2026-09-08'
};

/* ==================== الأسنان والفكّ ==================== */

DX_BODY['dry-socket'] = {
  symptoms: {
    ar: 'الأمر يبدأ خادعاً: تمرّ الساعات الأولى بعد القلع هادئة نسبياً وينحسر الألم كما يُتوقّع، ثم في اليوم الثاني أو الثالث ينقلب الحال فينفجر ألم عميق نابض في مكان القلع، أشدّ من ألم القلع نفسه، لا تُسكته المسكّنات المعتادة، وينتشر إلى الأذن والصدغ وجانب الوجه كلّه على الجهة نفسها حتى يظنّ المصاب أنّ أذنه هي المريضة. ويرى في المرآة تجويفاً فارغاً في مكان السنّ لونه رمادي أو مصفرّ وقد يظهر فيه العظم الأبيض عارياً بلا جلطة دم تغطّيه. ويصاحبه طعم كريه لا يزول بالمضمضة ورائحة فم نتنة. والحمّى والانتفاخ ليسا من صورته، فإن ظهرا فالغالب أنّ المشكلة عدوى لا سنخاً جافّاً.',
    en: 'It begins deceptively: the first hours after the extraction pass relatively quietly and the pain recedes as expected, then on the second or third day everything reverses and a deep throbbing pain erupts at the extraction site, worse than the extraction itself, unquieted by the usual painkillers, spreading to the ear, the temple and the whole side of the face so the sufferer thinks his ear is the sick part. In the mirror he sees an empty hollow where the tooth was, grey or yellowish, sometimes with bare white bone showing and no blood clot covering it. A foul taste that mouthwash will not remove and a bad breath accompany it. Fever and swelling do not belong to this picture, and if they appear the problem is most likely infection rather than a dry socket.'
  },
  cause: {
    ar: 'بعد قلع أيّ سنّ تتكوّن في التجويف جلطة دموية تعمل عمل الضمّادة: تغطّي العظم والنهايات العصبية المكشوفة وتكون الأساس الذي ينمو عليه النسيج الجديد. والسنخ الجاف هو أن تنحلّ هذه الجلطة أو تسقط قبل أوانها فينكشف العظم للهواء والطعام واللعاب، فتتهيّج النهايات العصبية العارية ويولد هذا الألم العنيف. وأقوى ما يسبّب ذلك التدخين، لأنّ شفط الدخان يولّد ضغطاً سالباً يقتلع الجلطة وموادّه تعوق الالتئام، ثم المصّ بالشليمون والمضمضة القوية والبصق المتكرّر في اليوم الأول. ويزيد الخطر مع قلع ضرس العقل السفلي خاصّة إن كان صعباً أو منطمراً، ومع وجود التهاب سابق حول السنّ، وسوء نظافة الفم، وحبوب منع الحمل، وسابقة إصابة بالحالة نفسها.',
    en: 'After any tooth is pulled a blood clot forms in the hollow and acts as a dressing: it covers the bone and the exposed nerve endings and is the base on which new tissue grows. A dry socket is the dissolving or premature loss of this clot, leaving the bone open to air, food and saliva, so the bare nerve endings are irritated and this violent pain is born. The strongest cause is smoking, because drawing on a cigarette creates suction that pulls the clot out while its substances hinder healing, followed by sucking through a straw, vigorous rinsing and repeated spitting on the first day. Risk rises with extraction of a lower wisdom tooth, especially a difficult or impacted one, with previous inflammation around the tooth, poor mouth hygiene, contraceptive pills, and a previous episode of the same condition.'
  },
  diagnosis: {
    ar: 'التشخيص سريريّ ولا يحتاج غالباً إلى صورة. المفتاح توقيت الألم: قلع تمّ قبل يومين إلى أربعة، ثم ألم اشتدّ بدل أن يخفّ. ينظّف طبيب الأسنان التجويف بلطف ويفحصه بضوء ومرآة، فيرى الجلطة غائبة أو متفتّتة، ويلمح العظم عارياً وهو شديد الإيلام عند لمسه برفق، ويلاحظ رائحة مميّزة. ويجسّ ما حول السنخ واللثة ويتحسّس الرقبة بحثاً عن انتفاخ أو عقد لأنّ وجودهما يوجّه إلى عدوى لا إلى سنخ جافّ. وتُطلب صورة الأسنان الشعاعية إن كان الشكّ في بقيّة جذر أو شظيّة عظم أو قطعة سنّ تُركت في التجويف، أو إن استمرّ الألم رغم العلاج، أو إن كان الألم في الفكّ السفلي مصحوباً بخدر في الشفة فقد يكون العصب قد تأذّى أثناء القلع.',
    en: 'The diagnosis is clinical and usually needs no imaging. The key is the timing of the pain: an extraction two to four days earlier, then pain that has intensified instead of easing. The dentist gently cleans the hollow and inspects it with light and mirror, finding the clot absent or crumbled, glimpses bare bone that is exquisitely tender to a light touch, and notes a characteristic smell. He feels around the socket and gum and palpates the neck for swelling or nodes, since their presence points to infection rather than a dry socket. A dental radiograph is requested if a retained root, bone fragment or piece of tooth is suspected in the hollow, if pain persists despite treatment, or if lower-jaw pain comes with numbness of the lip, since the nerve may have been injured during the extraction.'
  },
  treatment: {
    ar: 'العلاج يجري في عيادة الأسنان ونتيجته سريعة ومريحة: يُغسل التجويف غسلاً لطيفاً بمحلول معقّم لإخراج بقايا الطعام والنسيج المتفتّت، ثم يُوضع فيه ضمّاد طبّي مهدّئ يغطّي العظم العاري ويقطع الألم خلال دقائق، ويُبدَّل هذا الضمّاد كلّ يوم أو يومين حتى ينمو نسيج جديد يغطّي العظم، وهذا يستغرق أيّاماً إلى أسبوع أو أكثر بحسب حجم التجويف. ويُوصف مسكّن مناسب يقرّره الطبيب، ولا يحتاج الأمر إلى مضاد حيوي إلا إن ثبتت عدوى فعلية بحمّى أو انتفاخ أو صديد. ويُطلب من المريض غسل التجويف بالماء والملح الفاتر بلطف بعد الأكل بمحقنة صغيرة، والامتناع التامّ عن التدخين والمصّ بالشليمون. والوقاية أهمّ من العلاج: منع التدخين قبل القلع وبعده، وترك المضمضة القوية في اليوم الأول.',
    en: 'Treatment is carried out in the dental clinic and its result is quick and comforting: the hollow is gently washed with an antiseptic solution to flush out food debris and broken-down tissue, then a soothing medicated dressing is placed to cover the bare bone and cut the pain within minutes, and this dressing is changed every day or two until new tissue grows over the bone, which takes days to a week or more depending on the size of the hollow. A suitable painkiller is prescribed as the doctor decides, and an antibiotic is not needed unless real infection is proved by fever, swelling or pus. The patient is asked to rinse the hollow gently with warm salt water after meals using a small syringe, and to abstain completely from smoking and from sucking through a straw. Prevention matters more than treatment: no smoking before and after the extraction, and no vigorous rinsing on the first day.'
  },
  seeDoctor: {
    ar: 'اتّصل بطبيب أسنانك وخذ موعداً في اليوم نفسه إن اشتدّ الألم بعد القلع بدل أن يخفّ، خصوصاً في اليوم الثاني إلى الرابع، أو إن انتشر إلى أذنك وصدغك، أو رأيت التجويف فارغاً بلا جلطة، أو لم تنفع المسكّنات. ولا تنتظر أسبوعاً ولا تحاول العلاج بمواد من عندك داخل التجويف. واذهب إلى الطوارئ فوراً إن ارتفعت حرارتك، أو انتفخ وجهك أو أرضية فمك، أو صعب عليك فتح الفم أو البلع أو التنفّس، أو انتشر الاحمرار إلى الرقبة، فهذه علامات عدوى منتشرة لا سنخ جافّ. وراجع الطبيب أيضاً إن نزفت من مكان القلع نزفاً لا يقف بالضغط على شاش نصف ساعة، أو بقي خدر في شفتك أو لسانك بعد زوال أثر البنج بيوم، أو أحسست بشظيّة صلبة في التجويف.',
    en: 'Telephone your dentist and take a same-day appointment if pain after an extraction worsens instead of easing, especially on the second to fourth day, if it spreads to your ear and temple, if you see the hollow empty with no clot, or if painkillers do not work. Do not wait a week and do not try to treat it with substances of your own inside the socket. Go to the emergency department at once if your temperature rises, if your face or the floor of your mouth swells, if opening your mouth, swallowing or breathing becomes difficult, or if redness spreads to the neck, since these are signs of spreading infection rather than a dry socket. See the doctor too if bleeding from the site does not stop with half an hour of pressure on gauze, if numbness of your lip or tongue persists a day after the anaesthetic has worn off, or if you feel a hard fragment in the hollow.'
  },
  updated: '2026-09-08'
};

DX_BODY['malocclusion'] = {
  symptoms: {
    ar: 'أوّل ما يلاحظه الناس شكل الأسنان نفسه: أسنان متراكبة يركب بعضها بعضاً لضيق الفكّ، أو فراغات بينها، أو أسنان علوية بارزة إلى الأمام، أو فكّ سفلي متقدّم على العلوي، أو فجوة تبقى بين الأسنان الأمامية عند إطباق الفم فلا تُقطع بها اللقمة. ثم تظهر آثار عملية: طعام ينحشر دائماً في موضع بعينه، وتسوّس متكرّر في الأسنان المتزاحمة لأنّ الفرشاة لا تصل بينها، والتهاب لثة في المواضع نفسها. ويشكو بعضهم من عضّ باطن الخدّ أو اللسان بلا قصد، ومن تعب في عضلات المضغ وصداع في الصدغ آخر النهار، ومن طقطقة في مفصل الفكّ. وقد يتأثّر النطق ببعض الحروف، ويتآكل طرف بعض الأسنان تآكلاً غير متساوٍ من الاحتكاك الخاطئ.',
    en: 'The first thing people notice is the look of the teeth themselves: teeth overlapping one another because the jaw is narrow, or gaps between them, or upper teeth jutting forwards, or a lower jaw set ahead of the upper, or a space that stays between the front teeth when the mouth closes so a bite cannot be cut with them. Practical effects then appear: food packing always in one particular spot, repeated decay in crowded teeth because the brush cannot reach between them, and gum inflammation in the same places. Some complain of accidentally biting the inner cheek or tongue, of tiredness in the chewing muscles and a temple headache at the end of the day, and of clicking in the jaw joint. Speech may be affected for certain sounds, and the tips of some teeth wear unevenly from faulty contact.'
  },
  cause: {
    ar: 'الأساس عدم تناسب بين حجم الأسنان وحجم الفكّ الذي يحملها، وأكثره موروث: يرث الطفل أسنان أحد والديه وفكّ الآخر فلا تتّسع لها. وتضاف إليه أسباب مكتسبة تبدأ في الطفولة: مصّ الإبهام أو اللهّاية أو الرضّاعة بعد سنّ معيّنة فيدفع الضغط الأسنان الأمامية للأمام، والتنفّس من الفم بسبب لحمية أو لوزتين متضخّمتين أو انسداد أنفي مزمن لأنّ الفم المفتوح دائماً يغيّر نموّ الوجه والفكّ العلوي، ودفع اللسان على الأسنان عند البلع، وقضم الأظافر. ومنها فقدان سنّ لبني قبل أوانه بتسوّس أو ضربة، فتنجرف الأسنان المجاورة إلى فراغه وتغلق مكان السنّ الدائم القادم. ويضاف ضرس العقل حين يدفع الصفّ من الخلف، وفقدان أسنان في الكبر بلا تعويض، والكسور والعادات المهنية.',
    en: 'The basis is a mismatch between the size of the teeth and the size of the jaw carrying them, and most of it is inherited: the child inherits one parent teeth and the other jaw, and they do not fit. Acquired causes beginning in childhood are added: thumb, dummy or bottle sucking beyond a certain age, whose pressure pushes the front teeth forwards; mouth breathing from adenoids, enlarged tonsils or chronic nasal blockage, since a permanently open mouth alters the growth of the face and upper jaw; pushing the tongue against the teeth when swallowing; and nail biting. Among them is early loss of a milk tooth to decay or a blow, after which neighbouring teeth drift into the gap and close the place of the coming permanent tooth. Add the wisdom tooth pushing the row from behind, tooth loss in adulthood without replacement, fractures, and occupational habits.'
  },
  diagnosis: {
    ar: 'يبدأ تقويم الأسنان بفحص سريري كامل: ينظر الطبيب إلى تناسق الوجه من الأمام والجانب وإلى خطّ منتصف الأسنان، ويطلب منك الإطباق ليرى علاقة الأضراس ببعضها ومقدار تراكب الأسنان الأمامية أفقياً ورأسياً، ويقيس ازدحام الصفّ بمقارنة مجموع عرض الأسنان بالمسافة المتاحة في القوس. ويفحص مفصل الفكّ وحركته وأصواته وعضلات المضغ، واللثة والتسوّس لأنّهما يُعالَجان قبل بدء التقويم. ثم تُؤخذ صورة بانورامية للفكّين لعدّ الأسنان ورؤية المنطمر وضرس العقل والجذور، وصورة جانبية للرأس لقياس زوايا الفكّين وعلاقتهما بقاعدة الجمجمة وهي التي تفرّق مشكلة الأسنان وحدها عن مشكلة في حجم الفكّ. وتُؤخذ نماذج أو مسح رقمي للفكّين وصور فوتوغرافية للتخطيط والمقارنة.',
    en: 'Orthodontic assessment begins with a full clinical examination: the doctor looks at the symmetry of the face from the front and side and at the midline of the teeth, asks you to bite so he can see how the molars relate and how far the front teeth overlap horizontally and vertically, and measures crowding by comparing the summed width of the teeth with the space available in the arch. He examines the jaw joint, its movement and sounds, the chewing muscles, and the gums and decay, since both are treated before orthodontics begins. A panoramic radiograph of both jaws is then taken to count the teeth and see any impacted tooth, wisdom teeth and roots, and a side view of the head to measure the angles of the jaws and their relation to the skull base, which separates a problem of the teeth alone from a problem of jaw size. Models or a digital scan of both jaws and photographs are taken for planning and comparison.'
  },
  treatment: {
    ar: 'الخطّة تتبع العمر وسبب المشكلة. في الطفولة يُتدخّل مبكراً لتوجيه النموّ: موسّع للفكّ العلوي الضيّق، وأجهزة تصحّح عادة المصّ أو دفع اللسان، وحافظ مسافة إن فُقد سنّ لبني قبل أوانه، ومعالجة سبب التنفّس الفموي عند طبيب الأنف والأذن والحنجرة لأنّ إهماله يفسد كلّ ما بعده. وفي المراهقة والبلوغ الأساس هو التقويم الثابت أو الشفّاف الذي ينقل الأسنان تدريجياً خلال شهور إلى سنتين، وقد يسبقه قلع بعض الأسنان لتوفير مكان حين يكون الازدحام شديداً. وإن كانت المشكلة في حجم الفكّ نفسه لا في مواضع الأسنان فقد يلزم دمج التقويم مع جراحة الفكّين بعد اكتمال النموّ. وبعد أيّ علاج يأتي المثبّت وهو ركن لا يُهمل، فالأسنان تميل للعودة إلى مواضعها القديمة إن تُرك.',
    en: 'The plan follows the age and the cause. In childhood, early intervention guides growth: an expander for a narrow upper jaw, appliances to correct a sucking or tongue-thrusting habit, a space maintainer if a milk tooth is lost early, and treatment of the cause of mouth breathing with an ear, nose and throat doctor, since neglecting it spoils everything that follows. In adolescence and adulthood the mainstay is fixed or clear orthodontics, moving the teeth gradually over months to two years, sometimes preceded by extraction of some teeth to create space when crowding is severe. If the problem lies in the size of the jaw itself rather than the position of the teeth, orthodontics may need to be combined with jaw surgery after growth is complete. After any treatment comes the retainer, a pillar never to be neglected, since teeth tend to drift back to their old places if it is abandoned.'
  },
  seeDoctor: {
    ar: 'ليست حالة طوارئ، لكن اعرض طفلك على طبيب أسنان أو أخصّائي تقويم في سنّ السابعة تقريباً ولو بدت أسنانه سليمة، لأنّ بعض المشكلات في نموّ الفكّ لا يُصلَح إلا في نافذة زمنية تنتهي مع اكتمال النموّ. واطلب موعداً قبل ذلك إن رأيت سنّاً دائمة تبزغ خلف صفّ الأسنان اللبنية أو أمامه، أو فقد طفلك سنّاً لبنية مبكراً، أو استمرّ يمصّ إبهامه بعد سنّ الخامسة، أو كان ينام فاغراً فمه ويشخر ويتنفّس من فمه نهاراً. وراجع الطبيب في أيّ عمر إن صعب عليك المضغ أو قطع الطعام، أو تكرّر التسوّس والتهاب اللثة في الموضع نفسه، أو صرت تعضّ خدّك، أو ظهر ألم وطقطقة في مفصل الفكّ، أو تغيّرت إطباقتك فجأةً فهذا الأخير يستدعي فحصاً في أيّام لا شهور.',
    en: 'This is not an emergency, but have your child seen by a dentist or orthodontist at about the age of seven even if the teeth look fine, because some problems of jaw growth can only be corrected within a window that closes as growth completes. Ask for an appointment sooner if you see a permanent tooth erupting behind or in front of the row of milk teeth, if your child lost a milk tooth early, if he still sucks his thumb after the age of five, or if he sleeps with his mouth open, snores and breathes through his mouth by day. See the doctor at any age if chewing or biting food becomes hard, if decay and gum inflammation keep recurring in the same spot, if you have begun biting your cheek, if pain and clicking appear in the jaw joint, or if your bite suddenly changes, this last calling for assessment within days rather than months.'
  },
  updated: '2026-09-08'
};


/* ==================== البلعوم والحنجرة والبلع ==================== */

DX_BODY['tonsil-stones'] = {
  symptoms: {
    ar: 'أكثر ما يدفع الناس للسؤال عنها رائحة الفم: نفَس كريه ثابت لا تصلحه فرشاة ولا معجون ولا غسول، ويلاحظه المحيطون قبل صاحبه. ويشكو كثيرون من إحساس بجسم عالق في الحلق لا يزول بالبلع، أو من وخز خفيف في جانب واحد من الحلق يشتدّ عند البلع، أو من ألم مبهم يمتدّ إلى الأذن على الجهة نفسها. وقد يسعل الشخص فجأةً فتخرج حبيبة بيضاء أو صفراء صلبة صغيرة ذات رائحة نتنة جداً حين تُسحق، فيعرف حينئذ سبب ما يجده. وقد يرى في المرآة بفتح الفم نقاطاً بيضاء غائرة في ثنايا اللوزة يظنّها التهاباً. وأكثر المصابين بلا حمّى ولا احمرار ولا تعب عام، وهذا ما يفرّقها عن التهاب اللوزتين.',
    en: 'What most drives people to ask about them is breath odour: a persistent foul breath that no brush, paste or mouthwash corrects, noticed by those around before the person himself. Many complain of the feeling of something lodged in the throat that swallowing does not clear, of a slight prickling on one side of the throat that sharpens on swallowing, or of a vague pain running to the ear on the same side. A person may cough suddenly and bring up a small hard white or yellow granule with a very foul smell when crushed, and so learn the cause of what he had been feeling. He may see in the mirror, on opening his mouth, white dots sunk in the folds of the tonsil and take them for infection. Most sufferers have no fever, no redness and no general fatigue, which is what separates this from tonsillitis.'
  },
  cause: {
    ar: 'سطح اللوزتين ليس أملس بل تخترقه جيوب وثنايا عميقة، وهي جزء طبيعي من تكوينهما تزيد المساحة التي تلتقي فيها الميكروبات بالجهاز المناعي. وفي هذه الجيوب تتجمّع بقايا الطعام والخلايا الميتة المتساقطة من بطانة الفم والمخاط والبكتيريا، فتتراكم وتتصلّب مع الوقت وتترسّب فيها أملاح الكالسيوم فتصير كتلاً بيضاء صلبة. والرائحة تأتي من مركّبات كبريتية تنتجها بكتيريا لا هوائية تعيش في عمق هذه الجيوب. ويزيد تكوّنها عند من كانت جيوب لوزهم واسعة أو من تكرّرت عندهم التهابات اللوزتين فتندّبت الجيوب واتّسعت، ومع جفاف الفم وقلّة اللعاب، وسوء نظافة الفم، والتدخين، والارتجاع الحمضي، والتنقيط الأنفي الخلفي. وليست عدوى ولا معدية ولا خطيرة ولا تسبّب سرطاناً.',
    en: 'The surface of the tonsils is not smooth but riddled with deep pockets and folds, a natural part of their build that increases the area where microbes meet the immune system. In these pockets food debris, dead cells shed from the lining of the mouth, mucus and bacteria collect, pile up and harden with time as calcium salts settle in them, becoming hard white lumps. The odour comes from sulphur compounds produced by bacteria without oxygen living deep in these pockets. Formation increases in those whose tonsil pockets are wide or who have had repeated tonsil infections that scarred and widened the pockets, and with a dry mouth and scanty saliva, poor mouth hygiene, smoking, acid reflux and post-nasal drip. They are not an infection, not contagious, not dangerous and do not cause cancer.'
  },
  diagnosis: {
    ar: 'التشخيص بالنظر في الأغلب: يفتح الطبيب فمك ويضغط اللسان بخافض ويسلّط ضوءاً على اللوزتين فيرى النقاط البيضاء أو الصفراء داخل الجيوب، وقد يلمسها بأداة رفيعة فتتحرّك كالحصاة الصلبة بخلاف الصديد الذي يُمسح. ويسأل عن الحمّى وألم البلع الشديد والتعب لأنّ وجودها يوجّه إلى التهاب لوزتين لا إلى حصوات، ويجسّ الرقبة بحثاً عن عقد. وحين تكون الحصاة عميقة لا تُرى بالنظر رغم الأعراض قد تظهر مصادفةً في تصوير مقطعي أو صورة أسنان بانورامية أُجريت لسبب آخر، فتبدو نقطة متكلّسة في موضع اللوزة. ويبقى أهمّ عمل تشخيصي هو استبعاد أسباب رائحة الفم الأخرى: تسوّس، والتهاب لثة، وجفاف فم، وارتجاع، والتهاب جيوب مزمن، فقد تجتمع أكثر من علّة في شخص واحد.',
    en: 'The diagnosis is usually made by looking: the doctor opens your mouth, presses the tongue down with a depressor and shines a light on the tonsils to see the white or yellow dots inside the pockets, and may touch them with a fine instrument so they move like a hard stone, unlike pus which wipes away. He asks about fever, severe pain on swallowing and fatigue, since their presence points to tonsillitis rather than stones, and feels the neck for nodes. When a stone lies deep and cannot be seen despite symptoms, it may appear by chance on a computed tomography scan or a panoramic dental radiograph taken for another reason, showing as a calcified dot at the tonsil. The most important diagnostic work remains excluding other causes of bad breath: decay, gum disease, dry mouth, reflux and chronic sinusitis, since more than one cause may exist in the same person.'
  },
  treatment: {
    ar: 'أكثر الحصوات لا تحتاج أكثر من تدبير منزلي بسيط: الغرغرة بالماء والملح الفاتر بقوّة بعد الأكل، والإكثار من شرب الماء، وتنظيف الفم واللسان جيداً، وقد تنفع مضمضة الفم بجهاز الريّ المائي على أضعف قوّة موجّهاً بحذر شديد نحو الجيب فتخرج الحصاة. ويُنصح بشدّة بترك محاولة نبشها بعود أو دبّوس أو أيّ أداة حادّة، لأنّ اللوزة تنزف بسهولة وقد يجرحها ذلك ويسبّب عدوى. وإن كانت كبيرة أو متكرّرة أو مؤلمة فيمكن لطبيب الأنف والأذن والحنجرة إخراجها في العيادة. وحين تتكرّر كثيراً وتفسد جودة الحياة فهناك خياران: كيّ الجيوب وطمسها بالليزر أو بالترددات الراديوية، أو استئصال اللوزتين وهو الحلّ الجذري ويُترك للحالات الشديدة بعد موازنة فوائده ومخاطره.',
    en: 'Most stones need no more than simple home measures: vigorous gargling with warm salt water after meals, drinking plenty of water, cleaning the mouth and tongue well, and sometimes rinsing with a water flosser on its weakest setting aimed very carefully at the pocket, which flushes the stone out. It is strongly advised not to try digging them out with a stick, pin or any sharp implement, since the tonsil bleeds easily and this can wound it and cause infection. If a stone is large, recurrent or painful, an ear, nose and throat doctor can remove it in the clinic. When they recur often and spoil quality of life there are two options: sealing and obliterating the pockets with laser or radiofrequency, or removing the tonsils, the radical solution reserved for severe cases after weighing benefits against risks.'
  },
  seeDoctor: {
    ar: 'ليست حالة طوارئ في ذاتها. احجز موعداً عند طبيب أنف وأذن وحنجرة إن تكرّرت الحصوات كثيراً أو أزعجتك رائحة الفم رغم نظافة أسنانك وسلامتها، أو إن أحسست بجسم عالق في حلقك أكثر من أسبوعين. واطلب موعداً عاجلاً لا يُؤجَّل إن كان الأمر في جانب واحد فقط وثابتاً: لوزة واحدة متضخّمة بوضوح عن الأخرى ولا تصغر، أو قرحة على اللوزة، أو ألم مستمرّ في الأذن على جهة واحدة بأذن سليمة، أو خروج دم مع البصاق، أو كتلة في الرقبة، أو نقص وزن، أو صعوبة بلع تزداد، خصوصاً إن كنت مدخّناً. واذهب إلى الطوارئ إن ارتفعت حرارتك مع ألم شديد في جانب واحد وصعوبة في فتح الفم وتغيّر صوتك، فهذه صورة خرّاج حول اللوزة لا حصوات.',
    en: 'This is not in itself an emergency. Book an appointment with an ear, nose and throat doctor if stones recur often, if the breath odour troubles you despite clean and healthy teeth, or if you have felt something lodged in your throat for more than two weeks. Ask for an urgent, unpostponed appointment if the problem is on one side only and persistent: one tonsil clearly larger than the other and not shrinking, an ulcer on the tonsil, continuous one-sided ear pain with a healthy ear, blood in the spit, a lump in the neck, weight loss, or worsening difficulty swallowing, especially if you smoke. Go to the emergency department if your temperature rises with severe one-sided pain, difficulty opening the mouth and a changed voice, since this is the picture of an abscess beside the tonsil, not of stones.'
  },
  updated: '2026-09-08'
};

DX_BODY['lpr'] = {
  symptoms: {
    ar: 'الشكوى الأشيع تنحنح مستمرّ لا إرادي عشرات المرّات في اليوم، وإحساس بلقمة أو كرة عالقة في وسط الحلق لا تنزل ولا تطلع، وبحّة تكون أسوأ ما تكون بعد الاستيقاظ ثم تتحسّن مع اليوم. ويشكو المصاب من مخاط لزج يشعر أنّه ينزل من خلف أنفه فيبلعه ويكرّر تنظيف حلقه، ومن سعال جافّ مزعج بعد الأكل وعند الاستلقاء، ومن حرقة أو خشونة في الحلق، ومن تعب الصوت السريع عند الكلام الطويل. وقد يستيقظ ليلاً فجأةً وهو يختنق ويسعل بشدّة. والمحيّر أنّ أكثر هؤلاء لا يشعرون بحرقة الصدر المعروفة إطلاقاً، ولهذا سُمّي الارتجاع الصامت، فيدور المريض بين طبيب الصدر والحساسية والأنف سنين قبل أن يُعرف السبب.',
    en: 'The commonest complaint is constant involuntary throat-clearing dozens of times a day, a feeling of a lump or ball stuck in the middle of the throat that will neither go down nor come up, and hoarseness at its worst on waking that improves as the day goes on. The sufferer complains of sticky mucus he feels running down behind his nose which he swallows while repeatedly clearing his throat, of an annoying dry cough after eating and on lying down, of burning or roughness in the throat, and of a voice that tires quickly in long conversation. He may wake suddenly at night choking and coughing hard. What baffles is that most of these people feel no classic chest heartburn at all, which is why it is called silent reflux, so the patient circles between chest, allergy and nose doctors for years before the cause is known.'
  },
  cause: {
    ar: 'بين المعدة والحلق صمّامان: واحد أسفل المريء وآخر أعلاه عند مدخل الحنجرة. وحين يرتخي الصمّام العلوي أو يضعف يصعد ما في المعدة إلى البلعوم والحنجرة. والفارق المهمّ عن ارتجاع المريء المعروف أنّ بطانة المريء تحتمل قدراً من الحمض، أمّا نسيج الحنجرة فرقيق شديد الحساسية فتكفيه دفعات قليلة جداً ليتهيّج ويتورّم، ولذلك يشتكي هؤلاء بلا حرقة صدر. ويسهم في الأذى إنزيم هاضم يصعد مع الحمض ويبقى فاعلاً في نسيج الحنجرة. وأهمّ ما يهيّئ لذلك زيادة الوزن وكبر محيط البطن، والأكل الدسم والحارّ والحوامض والشوكولاتة والنعناع، والقهوة والمشروبات الغازية والكحول، والأكل قبل النوم مباشرةً، والوجبات الكبيرة، والتدخين، والفتق الحجابي، والحمل، والانحناء أو رفع الأثقال بعد الأكل، والضغط النفسي.',
    en: 'Between the stomach and the throat lie two valves: one at the bottom of the gullet and one at its top by the entrance of the voice box. When the upper valve slackens or weakens, stomach contents rise into the throat and larynx. The important difference from ordinary reflux is that the lining of the gullet tolerates a degree of acid, whereas the tissue of the larynx is thin and highly sensitive, so very few episodes suffice to irritate and swell it, which is why these people complain without chest burning. A digestive enzyme rising with the acid and remaining active in laryngeal tissue adds to the damage. What most predisposes is weight gain and a large waist, fatty, spicy and sour food, chocolate and mint, coffee, fizzy drinks and alcohol, eating just before sleep, large meals, smoking, a hiatus hernia, pregnancy, bending or lifting after eating, and mental stress.'
  },
  diagnosis: {
    ar: 'يبدأ الأمر بقصّة المريض لأنّها أهمّ ما يوجّه: توقيت الشكوى ونمطها وعلاقتها بالوجبات والنوم. ثم يفحص الطبيب الحلق والأنف والرقبة، والفحص الحاسم هو منظار الحنجرة المرن الرفيع الذي يمرّ من الأنف بلا تخدير عام فيرى الحبال الصوتية والمنطقة خلفها، فتظهر علامات التهيّج: احمرار وتورّم في الجزء الخلفي من الحنجرة، وتورّم الحبال، وسماكة المخاط. لكن هذه العلامات ليست قاطعة لأنّها تظهر عند أناس أصحّاء وعند المدخّنين، ولذلك يُشخَّص المرض بمجموع الأعراض والمنظار والاستجابة للتدبير. وإن بقي الشكّ أو لم يتحسّن المريض يُلجأ إلى قياس درجة الحموضة في البلعوم على مدى أربع وعشرين ساعة، وقد يُطلب منظار المعدة إن كان هناك عسر بلع أو نقص وزن أو فقر دم.',
    en: 'It begins with the patient story, the most directing element: the timing and pattern of the complaint and its relation to meals and sleep. The doctor then examines the throat, nose and neck, and the decisive examination is the fine flexible laryngoscope passed through the nose without general anaesthesia to see the vocal cords and the area behind them, where signs of irritation appear: redness and swelling of the back part of the larynx, swollen cords and thickened mucus. These signs are not conclusive, however, since they occur in healthy people and in smokers, so the disease is diagnosed by the sum of symptoms, endoscopy and response to management. If doubt remains or the patient does not improve, acidity in the throat is measured over twenty-four hours, and gastroscopy may be requested if there is difficulty swallowing, weight loss or anaemia.'
  },
  treatment: {
    ar: 'العمود الفقري للعلاج تغيير العادات، ونتائجه أفضل من أيّ دواء إن التزم المريض: خفض الوزن، وترك التدخين، والامتناع عن الأكل قبل النوم بثلاث ساعات على الأقلّ، ورفع رأس السرير من قوائمه لا بوسادة إضافية، وتصغير الوجبات وتكثيرها، وتقليل الدهون والحوامض والحارّ والشوكولاتة والنعناع والقهوة والغازيات. ويُضاف تدبير خاصّ بالصوت: الإكثار من الماء، والامتناع عن التنحنح لأنّه يصدم الحبال ويزيد التورّم فيزيد الرغبة في التنحنح في حلقة مفرغة، ويُستعاض عنه بابتلاع رشفة ماء. وقد يصف الطبيب دواءً يخفّض حموضة المعدة لفترة يقرّرها ثم يعيد التقييم، وقد يضيف ما يشكّل طبقة حاجزة بعد الوجبات. والتحسّن هنا بطيء يحتاج شهرين إلى ثلاثة قبل الحكم، بخلاف حرقة الصدر التي تهدأ بأيّام.',
    en: 'The backbone of treatment is changing habits, and its results beat any medicine if the patient keeps to them: losing weight, giving up smoking, not eating for at least three hours before sleep, raising the head of the bed on its legs rather than with an extra pillow, and making meals smaller and more frequent while cutting fat, sour and spicy food, chocolate, mint, coffee and fizzy drinks. Voice care is added: plenty of water, and avoiding throat-clearing, which slams the cords together and increases swelling, which in turn increases the urge to clear in a vicious circle, replaced instead by swallowing a sip of water. The doctor may prescribe something to lower stomach acidity for a period he decides, then reassess, and may add something that forms a barrier layer after meals. Improvement here is slow, needing two to three months before judgement, unlike chest heartburn which settles in days.'
  },
  seeDoctor: {
    ar: 'احجز موعداً عند طبيب أنف وأذن وحنجرة إن استمرّت بحّة صوتك أكثر من ثلاثة أسابيع، وهذه قاعدة لا تُتساهل فيها خصوصاً إن كنت مدخّناً أو تشرب الكحول، لأنّ سرطان الحنجرة يبدأ ببحّة تشبه هذه تماماً ولا يفرّقهما إلا المنظار. واطلب موعداً كذلك إن لم تتحسّن أعراضك بعد شهرين من الالتزام الجادّ. واذهب إلى الطوارئ إن ضاق نفسك أو سمعت صفيراً في شهيقك، أو عجزت عن ابتلاع ريقك، أو صار الطعام يعلق فعلاً في طريقه لا مجرّد إحساس، أو خرج دم مع السعال أو القيء، أو نقص وزنك بلا قصد، أو ظهرت كتلة في رقبتك، أو ابتلعت طعاماً فانحشر. وانتبه أنّ ألماً في الصدر مع تعرّق وضيق نفس ليس ارتجاعاً حتى يُثبت العكس، فاطلب الإسعاف.',
    en: 'Book an appointment with an ear, nose and throat doctor if your hoarseness lasts more than three weeks; this is a rule not to be relaxed, especially if you smoke or drink alcohol, because laryngeal cancer begins with a hoarseness exactly like this and only endoscopy tells them apart. Ask for an appointment too if your symptoms have not improved after two months of serious effort. Go to the emergency department if your breathing tightens or you hear a whistle on breathing in, if you cannot swallow your own saliva, if food genuinely sticks on its way rather than merely feeling so, if blood appears with cough or vomit, if you lose weight unintentionally, if a lump appears in your neck, or if swallowed food becomes impacted. Note too that chest pain with sweating and breathlessness is not reflux until proved otherwise, so call an ambulance.'
  },
  updated: '2026-09-08'
};

DX_BODY['dysphagia'] = {
  symptoms: {
    ar: 'يفرّق المريض بين صورتين. الأولى صعوبة في لحظة البلع نفسها: يسعل أو يشرق مع أوّل جرعة، أو يخرج الشراب من أنفه، أو يبقى الطعام في فمه لا يقدر على دفعه، أو يتغيّر صوته بعد البلع فيصير رطباً كأنّه يتكلّم عبر ماء، وقد يسيل لعابه. والثانية إحساس بأنّ اللقمة نزلت ثم وقفت في الصدر خلف عظمة القصّ بعد ثوانٍ، فيشرب ماءً ليدفعها أو ينتظر حتى تمرّ. ويلاحظ المصاب أنّه صار يطيل المضغ ويقطّع اللقم صغيرة ويتجنّب اللحم والخبز الجافّ والأرزّ، ويتأخّر عن الجميع على المائدة، وقد يمتنع عن الأكل مع الناس حرجاً. ومع الوقت ينقص الوزن ويجفّ، وقد تتكرّر التهابات الصدر بلا سبب ظاهر وهي علامة أنّ الطعام يدخل مجرى الهواء.',
    en: 'The patient distinguishes two pictures. In the first, difficulty comes at the very moment of swallowing: he coughs or chokes on the first mouthful, drink comes back through his nose, food stays in his mouth and he cannot push it, or his voice changes after swallowing to a wet sound as if speaking through water, and he may drool. In the second, the mouthful seems to go down and then stop in the chest behind the breastbone seconds later, so he drinks water to push it through or waits for it to pass. The sufferer notices he now chews longer, cuts small pieces, avoids meat, dry bread and rice, lags behind everyone at the table, and may avoid eating with others out of embarrassment. In time weight falls and he becomes dehydrated, and chest infections may recur with no apparent cause, a sign that food is entering the airway.'
  },
  cause: {
    ar: 'البلع فعل معقّد تشترك فيه عشرات العضلات وعدّة أعصاب في ثوانٍ، فأيّ خلل في أيّ حلقة يعطّله. وينقسم السبب بحسب موضعه. ففي الفم والحلق أشيع الأسباب أمراض عصبية: السكتة الدماغية وهي أكثرها، وباركنسون، والخرف، والتصلّب المتعدّد، ومرض العصبون الحركي، والوهن العضلي. ويضاف ضعف العضلات مع الشيخوخة، وجفاف الفم، وسوء الأسنان والأطقم، وأورام الفم والبلعوم والحنجرة، وآثار جراحة الرقبة أو إشعاعها. أمّا في المريء فالأسباب: تضيّق ناتج عن ارتجاع مزمن، والتهاب المريء اليوزيني عند الشباب، وتعذّر ارتخاء المريء، واضطرابات حركته، وورم المريء، وضغط من خارجه. وعلامة موجّهة مهمّة: صعوبة في الصلب وحده تدريجية توحي بتضيّق أو ورم، وصعوبة في الصلب والسائل معاً توحي باضطراب حركة.',
    en: 'Swallowing is a complex act in which dozens of muscles and several nerves cooperate within seconds, so a fault in any link disables it. The cause is grouped by its site. In the mouth and throat the commonest causes are neurological: stroke above all, then Parkinson disease, dementia, multiple sclerosis, motor neurone disease and myasthenia. Add muscle weakening with age, a dry mouth, poor teeth and dentures, tumours of the mouth, throat and larynx, and the effects of neck surgery or radiotherapy. In the gullet the causes are: narrowing from chronic reflux, eosinophilic oesophagitis in the young, failure of the gullet to relax, disorders of its movement, cancer of the gullet, and pressure from outside. One useful pointer: progressive difficulty with solids alone suggests a narrowing or tumour, while difficulty with both solids and liquids suggests a movement disorder.'
  },
  diagnosis: {
    ar: 'يبدأ الطبيب بأسئلة تحدّد الموضع: أين تحسّ أنّ الطعام يقف، وهل تسعل عند البلع أم بعده، وهل الصعوبة في الصلب وحده أم في السائل أيضاً، ومنذ متى وهل تتفاقم. ثم يفحص الفم والأسنان والأعصاب القحفية وقوّة العضلات، ويراقب المريض وهو يبلع رشفة ماء تحت النظر. وأدقّ فحص لبلع الفم والحلق هو تصوير البلع بالأشعة أثناء ابتلاع مادّة ظليلة بقوامات مختلفة، فهو يُظهر لحظة دخول الطعام مجرى الهواء ولو بلا سعال، ويبدّله أو يكمّله منظار مرن يراقب البلع مباشرةً. أمّا حين تشير القصّة إلى المريء فمنظار المعدة هو الأساس لأنّه يرى التضيّق والالتهاب والورم ويأخذ خزعة ويوسّع في الجلسة نفسها، ويُضاف قياس ضغوط المريء إن كان الشكّ في اضطراب حركة.',
    en: 'The doctor begins with questions that localise the problem: where you feel the food stop, whether you cough during or after swallowing, whether the difficulty is with solids alone or liquids too, how long it has lasted and whether it is worsening. He then examines the mouth, teeth, cranial nerves and muscle power, and watches the patient swallow a sip of water. The most accurate test of mouth and throat swallowing is a video X-ray taken while swallowing a contrast material of different consistencies, which shows the moment food enters the airway even without coughing, and is replaced or supplemented by a flexible endoscope watching the swallow directly. When the story points to the gullet, gastroscopy is the mainstay, since it sees narrowing, inflammation and tumour, takes a biopsy and dilates in the same session, with pressure measurement of the gullet added if a movement disorder is suspected.'
  },
  treatment: {
    ar: 'العلاج يتبع السبب، ولا يجوز الاكتفاء بتغيير قوام الطعام قبل معرفته. فالتضيّق يُوسَّع بالمنظار، والالتهاب اليوزيني يُعالَج بتدبير غذائي ودواء موضعي يقرّره الطبيب، وتعذّر الارتخاء له حلول بالمنظار أو الجراحة، والورم له مساره الخاصّ. أمّا صعوبة البلع العصبية فمحورها أخصّائي البلع والتخاطب: تقييم ثمّ تمارين لتقوية عضلات البلع، وتعليم مناورات تحمي مجرى الهواء مثل خفض الذقن نحو الصدر أو إدارة الرأس، وضبط قوام الطعام والشراب بما يناسب كلّ مريض. ويضاف تدبير عام مهمّ: الجلوس معتدلاً تماماً أثناء الأكل والبقاء كذلك بعده، والأكل ببطء بلقم صغيرة بلا حديث، ونظافة فم دقيقة لأنّها تقلّل التهاب الرئة الاستنشاقي. وحين يعجز البلع عن تأمين التغذية بأمان يُناقَش أنبوب تغذية مؤقّت أو دائم بقرار مشترك.',
    en: 'Treatment follows the cause, and it is not acceptable to settle for changing food consistency before knowing it. A narrowing is dilated endoscopically, eosinophilic inflammation is treated with dietary measures and a topical medicine chosen by the doctor, failure of relaxation has endoscopic or surgical solutions, and a tumour has its own path. Neurological swallowing difficulty centres on the swallowing and speech therapist: assessment, then exercises to strengthen the swallowing muscles, teaching manoeuvres that protect the airway such as tucking the chin to the chest or turning the head, and adjusting the consistency of food and drink to suit each patient. Important general measures are added: sitting fully upright during meals and staying so afterwards, eating slowly in small mouthfuls without talking, and meticulous mouth hygiene, which reduces aspiration pneumonia. When swallowing can no longer provide nutrition safely, a temporary or permanent feeding tube is discussed as a shared decision.'
  },
  seeDoctor: {
    ar: 'اطلب الإسعاف فوراً إن انحشرت لقمة ولم تعد تستطيع ابتلاع ريقك، أو اختنقت ولم يخرج ما علق بالسعال، أو ازرقّ لونك، أو ضاق نفسك. واحجز موعداً عاجلاً خلال أيام لا أسابيع إن ظهرت صعوبة بلع جديدة عند بالغ، خصوصاً إن كانت في الطعام الصلب وتزداد شهراً بعد شهر، أو صحبها نقص وزن غير مقصود، أو قيء، أو خروج دم، أو براز أسود، أو بحّة صوت، أو ألم عند البلع، أو كتلة في الرقبة، أو فقر دم. واذهب اليوم نفسه إن جاءت الصعوبة فجأةً مع ميلان في الوجه أو ضعف في طرف أو تلعثم في الكلام فقد تكون سكتة دماغية. وراجع الطبيب أيضاً إن تكرّرت التهابات صدرك أو حرارتك بعد الأكل، فالطعام قد يدخل رئتك بصمت وبلا سعال.',
    en: 'Call an ambulance at once if a mouthful becomes impacted and you can no longer swallow your own saliva, if you choke and coughing does not clear what is stuck, if you turn blue, or if your breathing tightens. Book an urgent appointment within days rather than weeks if new swallowing difficulty appears in an adult, especially with solid food and worsening month by month, or if it comes with unintended weight loss, vomiting, blood, black stools, hoarseness, pain on swallowing, a neck lump or anaemia. Go the same day if the difficulty came on suddenly with a droop of the face, weakness of a limb or slurred speech, since it may be a stroke. See the doctor too if your chest infections or fevers keep recurring after meals, since food may be entering your lungs silently and without any cough.'
  },
  updated: '2026-09-08'
};

DX_BODY['laryngeal-cancer'] = {
  symptoms: {
    ar: 'العلامة الأولى في أكثر الحالات بحّة في الصوت لا تزول: يبدأ الأمر كأنّه التهاب حنجرة عابر، لكن الصوت لا يعود بعد أسبوعين ولا ثلاثة، بل يزداد خشونةً وضعفاً حتى يصير همساً. وهذا حظّ حسن في الحقيقة، لأنّ الورم على الحبل الصوتي يفضح نفسه مبكراً وهو صغير. أمّا إن نشأ فوق الحبال أو تحتها فقد يتأخّر ظهوره وتكون أوّل علامة كتلة في الرقبة، أو ألماً في الحلق يمتدّ إلى الأذن على جهة واحدة والأذن سليمة، أو إحساساً بشيء عالق مع صعوبة بلع تتقدّم، أو ألماً عند البلع. ومع تقدّم الورم يظهر ضيق نفس وصفير في الشهيق عند المجهود ثم في الراحة، وسعال مزمن، وبصاق مخلوط بدم، ورائحة فم كريهة، ونقص وزن.',
    en: 'The first sign in most cases is hoarseness that will not clear: it starts as if it were a passing laryngitis, but the voice does not return after two weeks or three and instead grows rougher and weaker until it becomes a whisper. This is in truth good fortune, because a tumour on the vocal cord betrays itself early while still small. If it arises above or below the cords its appearance may be delayed and the first sign may be a lump in the neck, throat pain running to one ear while that ear is healthy, a feeling of something lodged with progressive difficulty swallowing, or pain on swallowing. As the tumour advances, breathlessness and a whistle on breathing in appear, first with exertion and then at rest, along with chronic cough, blood-streaked spit, foul breath and weight loss.'
  },
  cause: {
    ar: 'السبب الأكبر بلا منازع التدخين بكلّ صوره، والخطر يتناسب مع عدد السنوات وكمّية اليوم، ويشمل السجائر والغليون والمعسل. ويأتي الكحول ثانياً، والأخطر أن يجتمع الاثنان فيتضاعف الخطر أضعافاً لا يجمعه جمعاً بسيطاً لأنّ الكحول يذيب موادّ الدخان ويسهّل نفاذها إلى النسيج. وتضاف عوامل أخرى: التعرّض المهني الطويل لغبار الأسبستوس والأصباغ والأدخنة الصناعية وأبخرة اللحام، والارتجاع الحمضي المزمن الشديد، وفيروس الورم الحليمي البشري في بعض الأورام، وسوء التغذية وقلّة الخضار والفواكه، وسابقة إشعاع على الرقبة، وضعف المناعة. ويصيب الرجال أكثر من النساء ويكثر بعد سنّ الخمسين وإن كان يظهر أصغر من ذلك. والخبر المهمّ أنّ ترك التدخين يخفض الخطر مع مرور السنين.',
    en: 'The greatest cause by far is smoking in all its forms, the risk rising with the number of years and the daily amount, and including cigarettes, pipe and waterpipe. Alcohol comes second, and worst of all is the two together, which multiplies rather than merely adds risk, because alcohol dissolves the substances in smoke and eases their passage into the tissue. Other factors are added: long occupational exposure to asbestos dust, dyes, industrial fumes and welding vapours; severe chronic acid reflux; human papillomavirus in some tumours; poor nutrition with few vegetables and fruits; previous radiation to the neck; and weakened immunity. It affects men more than women and is commonest after the age of fifty, though it appears younger too. The important news is that stopping smoking lowers the risk over the years.'
  },
  diagnosis: {
    ar: 'الفحص الحاسم هو منظار الحنجرة: أنبوب مرن رفيع يمرّ من الأنف في العيادة بلا تخدير عام فيرى الحبال الصوتية وما فوقها وما تحتها ويقيّم حركتها، لأنّ توقّف حركة الحبل علامة مهمّة في تحديد مرحلة الورم. ويجسّ الطبيب الرقبة كلّها بحثاً عن عقد. ثم تُؤخذ خزعة تحت تخدير عام في منظار مباشر، وهي وحدها ما يثبت التشخيص ونوع الخلايا، وتُفحَص في الجلسة نفسها كلّ المنطقة لأنّ أوراماً ثانية قد توجد في الفم أو البلعوم أو المريء عند المدخّنين. وتُطلب صورة مقطعية أو رنين للرقبة والصدر لتحديد امتداد الورم وغزوه للغضروف وحالة العقد، وقد يُضاف مسح كامل للجسم. ويُقيَّم صوت المريض وبلعه قبل العلاج ليُقارَن بعده، وتُفحَص أسنانه إن كان الإشعاع وارداً.',
    en: 'The decisive examination is laryngoscopy: a fine flexible tube passed through the nose in the clinic without general anaesthesia, seeing the vocal cords and the areas above and below them and assessing their movement, since a cord that has stopped moving is an important sign in staging. The doctor palpates the whole neck for nodes. A biopsy is then taken under general anaesthesia at direct endoscopy, and it alone proves the diagnosis and the cell type, with the whole region inspected in the same session because second tumours may exist in the mouth, throat or gullet in smokers. Computed tomography or magnetic resonance of the neck and chest is requested to define the extent of the tumour, its invasion of cartilage and the state of the nodes, and a whole-body scan may be added. Voice and swallowing are assessed before treatment for later comparison, and the teeth are examined if radiotherapy is likely.'
  },
  treatment: {
    ar: 'القرار يتّخذه فريق متعدّد التخصّصات ويقوم على مرحلة الورم وموضعه ورغبة المريض في حفظ صوته. في المراحل المبكّرة يكون العلاج إمّا إشعاعاً موضعياً وإمّا جراحة بالليزر عبر الفم، وكلاهما يشفي نسبة عالية ويحفظ الحنجرة والصوت، ويقارن الفريق بينهما بحسب جودة الصوت المتوقّعة. وفي المراحل المتقدّمة يُجمَع بين الإشعاع والعلاج الكيميائي كي تُحفَظ الحنجرة، أو يُلجأ إلى استئصال الحنجرة كاملاً إن كان الورم واسعاً أو غزا الغضروف، ومعه رفع عقد الرقبة. ومن استُؤصلت حنجرته يتنفّس بعدها من فتحة في الرقبة، ويتعلّم الكلام من جديد بصمّام صوتي أو بالكلام المريئي أو بجهاز كهربائي، ويعود كثيرون إلى حياة قريبة من الطبيعية. وترك التدخين والكحول ركن في العلاج نفسه لا نصيحة، ويُتابَع المريض سنين.',
    en: 'The decision is taken by a multidisciplinary team and rests on the stage of the tumour, its site and the patient wish to keep his voice. In early stages treatment is either localised radiotherapy or laser surgery through the mouth, both of which cure a high proportion and preserve the larynx and the voice, the team comparing them by the expected voice quality. In advanced stages radiotherapy is combined with chemotherapy so the larynx may be preserved, or the larynx is removed entirely if the tumour is extensive or has invaded cartilage, together with clearance of the neck nodes. Anyone whose larynx is removed then breathes through an opening in the neck and learns to speak again with a voice valve, oesophageal speech or an electrical device, and many return to a life close to normal. Giving up tobacco and alcohol is part of the treatment itself, not advice, and the patient is followed for years.'
  },
  seeDoctor: {
    ar: 'القاعدة التي تنقذ الأرواح: أيّ بحّة صوت استمرّت أكثر من ثلاثة أسابيع تستدعي منظار حنجرة عند طبيب أنف وأذن وحنجرة، ولا تُقبل تفسيرات مطمئنة بلا نظر إلى الحبال، خصوصاً إن كنت مدخّناً أو تشرب الكحول أو تجاوزت الأربعين. واطلب موعداً عاجلاً إن صحب البحّة ألم في الأذن على جهة واحدة بأذن سليمة، أو كتلة في الرقبة، أو صعوبة بلع تتقدّم، أو ألم عند البلع، أو دم مع البصاق، أو نقص وزن، أو رائحة فم كريهة جديدة. واذهب إلى الطوارئ فوراً إن ضاق نفسك أو سمعت صفيراً عالياً في شهيقك أو صعب عليك التنفّس مستلقياً أو ازرقّت شفتاك، فانسداد مجرى الهواء عند مريض حنجرة حالة تُعالَج في دقائق لا ساعات.',
    en: 'The rule that saves lives: any hoarseness lasting more than three weeks calls for laryngoscopy with an ear, nose and throat doctor, and no reassuring explanation should be accepted without looking at the cords, especially if you smoke, drink alcohol or are over forty. Ask for an urgent appointment if the hoarseness comes with one-sided ear pain while that ear is healthy, a neck lump, progressive difficulty swallowing, pain on swallowing, blood in the spit, weight loss, or a new foul breath. Go to the emergency department at once if your breathing tightens, if you hear a loud whistle as you breathe in, if breathing becomes hard lying down, or if your lips turn blue, since airway obstruction in a patient with a laryngeal tumour is treated in minutes, not hours.'
  },
  updated: '2026-09-08'
};

DX_BODY['nasopharyngeal-carcinoma'] = {
  symptoms: {
    ar: 'أكثر ما يجيء به المريض أوّل مرّة كتلة في جانب الرقبة لا تؤلم ولا تصغر، يظنّها غدّة من التهاب حلق فيتناول لها مضاداً حيوياً فلا تتغيّر. والعلامة الثانية المميّزة انسداد أذن واحدة مع إحساس بامتلاء وضعف سمع، لأنّ الورم يسدّ فتحة القناة التي تهوّي الأذن الوسطى فيتجمّع خلف الطبلة سائل، وهذا عند بالغ لم يسبق له التهاب أذن أمر لافت جداً. ويشكو بعضهم من انسداد أنف مستمرّ في جهة واحدة، أو من مخاط مخلوط بخيوط دم يخرج من الأنف أو من الحلق عند التنحنح صباحاً، أو من رعاف متكرّر خفيف. وفي الحالات المتقدّمة يظهر صداع، وازدواج في الرؤية أو تدلّي جفن أو خدر في نصف الوجه حين يزحف الورم إلى الأعصاب عند قاعدة الجمجمة.',
    en: 'What most often brings the patient in for the first time is a painless lump in the side of the neck that does not shrink; he takes it for a gland from a sore throat and takes an antibiotic for it with no change. The second distinctive sign is blockage of one ear with a feeling of fullness and reduced hearing, because the tumour blocks the opening of the tube that ventilates the middle ear so fluid gathers behind the drum, and in an adult with no history of ear infection this is very striking. Some complain of persistent one-sided nasal blockage, of mucus streaked with threads of blood coming from the nose or throat on clearing it in the morning, or of repeated mild nosebleeds. In advanced cases headache appears, along with double vision, a drooping eyelid or numbness of half the face as the tumour creeps to the nerves at the skull base.'
  },
  cause: {
    ar: 'ينشأ هذا الورم في البلعوم الأنفي، وهو حجرة صغيرة خلف الأنف فوق سقف الحلق لا تُرى بالنظر في الفم، ولذلك يكبر بهدوء قبل أن يُكشف. وله ثلاثة أعمدة في السبب: فيروس إبشتاين بار الذي يصيب أغلب الناس في الطفولة ويبقى كامناً، ويوجد داخل خلايا هذا الورم بصورة ثابتة تجعله جزءاً من نشأته لا مصادفة؛ واستعداد وراثي يفسّر تجمّع الحالات في عائلات بعينها وفي مناطق جغرافية بعينها كجنوب الصين وجنوب شرق آسيا وشمال أفريقيا؛ وعوامل بيئية أهمّها الأسماك المملّحة المخزَّنة والأطعمة المحفوظة بالنترات التي تُؤكَل منذ الطفولة، والتدخين، والتعرّض للأدخنة والغبار الصناعي والفورمالديهايد. ويظهر في أعمار أصغر من كثير من السرطانات، وقد يصيب من هم في الثلاثينات والأربعينات.',
    en: 'This tumour arises in the nasopharynx, a small chamber behind the nose above the roof of the throat that cannot be seen by looking in the mouth, which is why it grows quietly before being found. Its cause rests on three pillars: the Epstein-Barr virus, which infects most people in childhood and stays dormant, and is found within the cells of this tumour so consistently that it is part of its origin rather than a coincidence; an inherited susceptibility that explains the clustering of cases in particular families and particular regions such as southern China, south-east Asia and North Africa; and environmental factors, chiefly stored salted fish and nitrate-preserved foods eaten from childhood, smoking, and exposure to fumes, industrial dust and formaldehyde. It appears at younger ages than many cancers and may strike people in their thirties and forties.'
  },
  diagnosis: {
    ar: 'المفتاح أن يُنظَر إلى المكان نفسه، فلا يكفي فحص الحلق بالنظر. يمرّر الطبيب منظاراً مرناً رفيعاً من الأنف إلى البلعوم الأنفي في العيادة فيرى السقف الخلفي مباشرةً، وهذا الفحص البسيط هو ما يكشف الورم غالباً أو ينفيه. وحين يُرى شيء تُؤخَذ خزعة منه وهي التي تثبت التشخيص. ومن الأخطاء الشائعة أن تُؤخَذ خزعة من كتلة الرقبة أوّلاً، والصواب البحث عن الأصل في البلعوم الأنفي قبل ذلك. وتُطلب صورة رنين مغناطيسي لأنّها أدقّ من غيرها في إظهار امتداد الورم إلى قاعدة الجمجمة والأنسجة الرخوة، مع تصوير مقطعي ومسح كامل للجسم لتحديد المرحلة. ويُقاس الحمض النووي للفيروس في الدم فيساعد في تقدير حجم المرض ومتابعته بعد العلاج. ويُفحَص السمع لأنّ سائل الأذن شائع.',
    en: 'The key is to look at the place itself, since inspecting the throat is not enough. The doctor passes a fine flexible endoscope through the nose to the nasopharynx in the clinic and sees the back roof directly, and this simple examination is usually what finds or excludes the tumour. When something is seen a biopsy is taken from it, and that is what proves the diagnosis. A common mistake is to biopsy the neck lump first; the correct course is to look for the origin in the nasopharynx before that. Magnetic resonance imaging is requested, being the most accurate at showing extension to the skull base and soft tissues, together with computed tomography and a whole-body scan for staging. Viral genetic material is measured in the blood, helping to gauge the amount of disease and to follow it after treatment. Hearing is tested, since middle-ear fluid is common.'
  },
  treatment: {
    ar: 'الجراحة ليست العلاج الأساسي هنا لأنّ موضع الورم عميق يصعب الوصول إليه، ولأنّ هذا النوع شديد الاستجابة للإشعاع. فالعمود الفقري للعلاج إشعاع دقيق موجّه بالتصوير يركّز أثره على الورم ويجنّب ما حوله من أعصاب وعين وغدد لعابية. وفي المراحل المتقدّمة أو حين تُصاب العقد يُضاف علاج كيميائي قبل الإشعاع أو معه أو بعده بحسب الخطّة، وقد يُستعمل علاج مناعي في الحالات المنتشرة أو العائدة. وتُترك الجراحة للعقد التي بقيت بعد العلاج أو لعودة موضعية محدودة. والرعاية الداعمة جزء أصيل: عناية بالفم والأسنان قبل الإشعاع، وتدبير جفاف الفم وتقرّح الغشاء وصعوبة البلع، وأنبوب تهوية للأذن إن لزم. والمتابعة طويلة بالمنظار والصور وقياس الفيروس في الدم لأنّ الكشف المبكّر للعودة يغيّر النتيجة.',
    en: 'Surgery is not the mainstay here, because the site of the tumour is deep and hard to reach and because this type responds strongly to radiation. The backbone of treatment is precise image-guided radiotherapy that concentrates its effect on the tumour while sparing the surrounding nerves, eye and salivary glands. In advanced stages or when nodes are involved, chemotherapy is added before, during or after the radiation according to the plan, and immunotherapy may be used in spread or recurrent disease. Surgery is reserved for nodes remaining after treatment or for limited local recurrence. Supportive care is an integral part: care of the mouth and teeth before radiotherapy, management of dry mouth, mucosal ulceration and swallowing difficulty, and a ventilation tube for the ear if needed. Follow-up is long, with endoscopy, imaging and blood measurement of the virus, since early detection of recurrence changes the outcome.'
  },
  seeDoctor: {
    ar: 'احجز موعداً عند طبيب أنف وأذن وحنجرة خلال أسبوعين واطلب منظاراً للبلعوم الأنفي إن ظهرت لك كتلة في الرقبة بلا ألم بقيت أكثر من أسبوعين ولم تصغر بمضاد حيوي، ولا تقبل تفسير الغدّة الملتهبة إن كنت بلا التهاب حلق. واطلبه كذلك إن انسدّت أذن واحدة وضعف سمعها بلا سبب وأنت بالغ، فهذه علامة يعرفها أطبّاء الأنف والأذن ولا يستهينون بها. وراجع الطبيب إن انسدّ منخر واحد باستمرار، أو خرج مخاط مخلوط بدم من أنفك أو حلقك، أو تكرّر رعافك من جهة واحدة. واطلب موعداً عاجلاً إن ظهر صداع مستمرّ جديد، أو ازدواج في الرؤية، أو تدلّي جفن، أو خدر في نصف الوجه أو الخدّ، فهذه علامات امتداد إلى الأعصاب لا تحتمل تأجيلاً.',
    en: 'Book an appointment with an ear, nose and throat doctor within two weeks and ask for a nasopharyngeal endoscopy if a painless neck lump has lasted more than two weeks and has not shrunk with an antibiotic, and do not accept the explanation of an inflamed gland if you have no sore throat. Ask for it too if one ear has blocked and its hearing has faded for no reason and you are an adult, since this is a sign ear, nose and throat doctors know and never take lightly. See the doctor if one nostril stays persistently blocked, if blood-streaked mucus comes from your nose or throat, or if nosebleeds recur from one side. Ask for an urgent appointment if a persistent new headache appears, or double vision, a drooping eyelid, or numbness of half the face or cheek, since these signal spread to the nerves and tolerate no delay.'
  },
  updated: '2026-09-08'
};

